/**
 * Diff generation and replace-mode utilities for the edit tool.
 *
 * Provides diff string generation and the replace-mode edit logic
 * used when not in patch mode.
 */
import * as Diff from 'diff';
import { resolveToCwd } from '../tools/path-utils';
import { previewPatch } from './applicator';
import { DEFAULT_FUZZY_THRESHOLD, findMatch } from './fuzzy';
import type { HashlineEdit } from './hashline';
import { applyHashlineEdits } from './hashline';
import { adjustIndentation, normalizeToLF, stripBom } from './normalize';
import type { DiffError, DiffResult, PatchInput } from './types';
import { EditMatchError } from './types';

// ═══════════════════════════════════════════════════════════════════════════
// Diff String Generation
// ═══════════════════════════════════════════════════════════════════════════

function countContentLines(content: string): number {
  const lines = content.split('\n');
  if (lines.length > 1 && lines[lines.length - 1] === '') {
    lines.pop();
  }
  return Math.max(1, lines.length);
}

function formatNumberedDiffLine(
  prefix: '+' | '-' | ' ',
  lineNum: number,
  width: number,
  content: string,
): string {
  const padded = String(lineNum).padStart(width, ' ');
  return `${prefix}${padded}|${content}`;
}

/**
 * Generate a unified diff string with line numbers and context.
 * Returns both the diff string and the first changed line number (in the new file).
 */
export function generateDiffString(
  oldContent: string,
  newContent: string,
  contextLines = 4,
): DiffResult {
  const parts = Diff.diffLines(oldContent, newContent);
  const output: string[] = [];

  const maxLineNum = Math.max(countContentLines(oldContent), countContentLines(newContent));
  const lineNumWidth = String(maxLineNum).length;

  let oldLineNum = 1;
  let newLineNum = 1;
  let lastWasChange = false;
  let firstChangedLine: number | undefined;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const raw = part.value.split('\n');
    if (raw[raw.length - 1] === '') {
      raw.pop();
    }

    if (part.added || part.removed) {
      // Capture the first changed line (in the new file)
      if (firstChangedLine === undefined) {
        firstChangedLine = newLineNum;
      }

      // Show the change
      for (const line of raw) {
        if (part.added) {
          output.push(formatNumberedDiffLine('+', newLineNum, lineNumWidth, line));
          newLineNum++;
        } else {
          output.push(formatNumberedDiffLine('-', oldLineNum, lineNumWidth, line));
          oldLineNum++;
        }
      }
      lastWasChange = true;
    } else {
      // Context lines - only show a few before/after changes
      const nextPartIsChange = i < parts.length - 1 && (parts[i + 1].added || parts[i + 1].removed);

      if (lastWasChange || nextPartIsChange) {
        let linesToShow = raw;
        let skipStart = 0;
        let skipEnd = 0;

        if (!lastWasChange) {
          // Show only last N lines as leading context
          skipStart = Math.max(0, raw.length - contextLines);
          linesToShow = raw.slice(skipStart);
        }

        if (!nextPartIsChange && linesToShow.length > contextLines) {
          // Show only first N lines as trailing context
          skipEnd = linesToShow.length - contextLines;
          linesToShow = linesToShow.slice(0, contextLines);
        }

        // Add ellipsis if we skipped lines at start
        if (skipStart > 0) {
          output.push(formatNumberedDiffLine(' ', oldLineNum, lineNumWidth, '...'));
          oldLineNum += skipStart;
          newLineNum += skipStart;
        }

        for (const line of linesToShow) {
          output.push(formatNumberedDiffLine(' ', oldLineNum, lineNumWidth, line));
          oldLineNum++;
          newLineNum++;
        }

        // Add ellipsis if we skipped lines at end
        if (skipEnd > 0) {
          output.push(formatNumberedDiffLine(oldLineNum, ' ', lineNumWidth, '...'));
          oldLineNum += skipEnd;
          newLineNum += skipEnd;
        }
      } else {
        // Skip these context lines entirely
        oldLineNum += raw.length;
        newLineNum += raw.length;
      }

      lastWasChange = false;
    }
  }

  return { diff: output.join('\n'), firstChangedLine };
}

// ═══════════════════════════════════════════════════════════════════════════
// Replace Mode Logic
// ═══════════════════════════════════════════════════════════════════════════

export interface ReplaceOptions {
  /** Allow fuzzy matching */
  fuzzy: boolean;
  /** Replace all occurrences */
  all: boolean;
  /** Similarity threshold for fuzzy matching */
  threshold?: number;
}

export interface ReplaceResult {
  /** The new content after replacements */
  content: string;
  /** Number of replacements made */
  count: number;
}

/**
 * Generate a unified diff string without file headers.
 * Returns both the diff string and the first changed line number (in the new file).
 */
export function generateUnifiedDiffString(
  oldContent: string,
  newContent: string,
  contextLines = 3,
): DiffResult {
  const patch = Diff.structuredPatch('', '', oldContent, newContent, '', '', {
    context: contextLines,
  });
  const output: string[] = [];
  let firstChangedLine: number | undefined;
  const maxLineNum = Math.max(countContentLines(oldContent), countContentLines(newContent));
  const lineNumWidth = String(maxLineNum).length;
  for (const hunk of patch.hunks) {
    output.push(`@@ -${hunk.oldStart},${hunk.oldLines} +${hunk.newStart},${hunk.newLines} @@`);
    let oldLine = hunk.oldStart;
    let newLine = hunk.newStart;
    for (const line of hunk.lines) {
      if (line.startsWith('-')) {
        if (firstChangedLine === undefined) firstChangedLine = newLine;
        output.push(formatNumberedDiffLine('-', oldLine, lineNumWidth, line.slice(1)));
        oldLine++;
        continue;
      }
      if (line.startsWith('+')) {
        if (firstChangedLine === undefined) firstChangedLine = newLine;
        output.push(formatNumberedDiffLine('+', newLine, lineNumWidth, line.slice(1)));
        newLine++;
        continue;
      }
      if (line.startsWith(' ')) {
        output.push(formatNumberedDiffLine(' ', oldLine, lineNumWidth, line.slice(1)));
        oldLine++;
        newLine++;
        continue;
      }
      output.push(line);
    }
  }

  return { diff: output.join('\n'), firstChangedLine };
}

/**
 * Find and replace text in content using fuzzy matching.
 */
export function replaceText(
  content: string,
  oldText: string,
  newText: string,
  options: ReplaceOptions,
): ReplaceResult {
  if (oldText.length === 0) {
    throw new Error('oldText must not be empty.');
  }
  const threshold = options.threshold ?? DEFAULT_FUZZY_THRESHOLD;
  let normalizedContent = normalizeToLF(content);
  const normalizedOldText = normalizeToLF(oldText);
  const normalizedNewText = normalizeToLF(newText);
  let count = 0;

  if (options.all) {
    // Check for exact matches first
    const exactCount = normalizedContent.split(normalizedOldText).length - 1;
    if (exactCount > 0) {
      return {
        content: normalizedContent.split(normalizedOldText).join(normalizedNewText),
        count: exactCount,
      };
    }

    // No exact matches - try fuzzy matching iteratively
    while (true) {
      const matchOutcome = findMatch(normalizedContent, normalizedOldText, {
        allowFuzzy: options.fuzzy,
        threshold,
      });

      const shouldUseClosest =
        options.fuzzy &&
        matchOutcome.closest &&
        matchOutcome.closest.confidence >= threshold &&
        (matchOutcome.fuzzyMatches === undefined || matchOutcome.fuzzyMatches <= 1);
      const match = matchOutcome.match || (shouldUseClosest ? matchOutcome.closest : undefined);
      if (!match) {
        break;
      }

      const adjustedNewText = adjustIndentation(
        normalizedOldText,
        match.actualText,
        normalizedNewText,
      );
      if (adjustedNewText === match.actualText) {
        break;
      }
      normalizedContent =
        normalizedContent.substring(0, match.startIndex) +
        adjustedNewText +
        normalizedContent.substring(match.startIndex + match.actualText.length);
      count++;
    }

    return { content: normalizedContent, count };
  }

  // Single replacement mode
  const matchOutcome = findMatch(normalizedContent, normalizedOldText, {
    allowFuzzy: options.fuzzy,
    threshold,
  });

  if (matchOutcome.occurrences && matchOutcome.occurrences > 1) {
    const previews = matchOutcome.occurrencePreviews?.join('\n\n') ?? '';
    const moreMsg =
      matchOutcome.occurrences > 5 ? ` (showing first 5 of ${matchOutcome.occurrences})` : '';
    throw new Error(
      `Found ${matchOutcome.occurrences} occurrences${moreMsg}:\n\n${previews}\n\n` +
        `Add more context lines to disambiguate.`,
    );
  }

  if (!matchOutcome.match) {
    return { content: normalizedContent, count: 0 };
  }

  const match = matchOutcome.match;
  const adjustedNewText = adjustIndentation(normalizedOldText, match.actualText, normalizedNewText);
  normalizedContent =
    normalizedContent.substring(0, match.startIndex) +
    adjustedNewText +
    normalizedContent.substring(match.startIndex + match.actualText.length);

  return { content: normalizedContent, count: 1 };
}

// ═══════════════════════════════════════════════════════════════════════════
// Preview/Diff Computation
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Compute the diff for an edit operation without applying it.
 * Used for preview rendering in the TUI before the tool executes.
 */
export async function computeEditDiff(
  path: string,
  oldText: string,
  newText: string,
  cwd: string,
  fuzzy = true,
  all = false,
  threshold?: number,
): Promise<DiffResult | DiffError> {
  if (oldText.length === 0) {
    return { error: 'oldText must not be empty.' };
  }
  const absolutePath = resolveToCwd(path, cwd);

  try {
    const file = Bun.file(absolutePath);
    try {
      if (!(await file.exists())) {
        return { error: `File not found: ${path}` };
      }
    } catch {
      return { error: `File not found: ${path}` };
    }

    let rawContent: string;
    try {
      rawContent = await file.text();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      return { error: message || `Unable to read ${path}` };
    }

    const { text: content } = stripBom(rawContent);
    const normalizedContent = normalizeToLF(content);
    const normalizedOldText = normalizeToLF(oldText);
    const normalizedNewText = normalizeToLF(newText);

    const result = replaceText(normalizedContent, normalizedOldText, normalizedNewText, {
      fuzzy,
      all,
      threshold,
    });

    if (result.count === 0) {
      // Get closest match for error message
      const matchOutcome = findMatch(normalizedContent, normalizedOldText, {
        allowFuzzy: fuzzy,
        threshold: threshold ?? DEFAULT_FUZZY_THRESHOLD,
      });

      if (matchOutcome.occurrences && matchOutcome.occurrences > 1) {
        const previews = matchOutcome.occurrencePreviews?.join('\n\n') ?? '';
        const moreMsg =
          matchOutcome.occurrences > 5 ? ` (showing first 5 of ${matchOutcome.occurrences})` : '';
        return {
          error: `Found ${matchOutcome.occurrences} occurrences in ${path}${moreMsg}:\n\n${previews}\n\nAdd more context lines to disambiguate.`,
        };
      }

      return {
        error: EditMatchError.formatMessage(path, normalizedOldText, matchOutcome.closest, {
          allowFuzzy: fuzzy,
          threshold: threshold ?? DEFAULT_FUZZY_THRESHOLD,
          fuzzyMatches: matchOutcome.fuzzyMatches,
        }),
      };
    }

    if (normalizedContent === result.content) {
      return {
        error: `No changes would be made to ${path}. The replacement produces identical content.`,
      };
    }

    return generateDiffString(normalizedContent, result.content);
  } catch (err) {
    return { error: err instanceof Error ? err.message : String(err) };
  }
}

/**
 * Compute the diff for a patch operation without applying it.
 * Used for preview rendering in the TUI before patch-mode edits execute.
 */
export async function computePatchDiff(
  input: PatchInput,
  cwd: string,
  options?: { fuzzyThreshold?: number; allowFuzzy?: boolean },
): Promise<DiffResult | DiffError> {
  try {
    const result = await previewPatch(input, {
      cwd,
      fuzzyThreshold: options?.fuzzyThreshold,
      allowFuzzy: options?.allowFuzzy,
    });
    const oldContent = result.change.oldContent ?? '';
    const newContent = result.change.newContent ?? '';
    const normalizedOld = normalizeToLF(stripBom(oldContent).text);
    const normalizedNew = normalizeToLF(stripBom(newContent).text);
    if (!normalizedOld && !normalizedNew) {
      return { diff: '', firstChangedLine: undefined };
    }
    return generateUnifiedDiffString(normalizedOld, normalizedNew);
  } catch (err) {
    return { error: err instanceof Error ? err.message : String(err) };
  }
}
/**
 * Compute the diff for a hashline operation without applying it.
 * Used for preview rendering in the TUI before hashline-mode edits execute.
 */
export async function computeHashlineDiff(
  input: { path: string; edits: HashlineEdit[]; move?: string },
  cwd: string,
): Promise<DiffResult | DiffError> {
  const { path, edits, move } = input;
  const absolutePath = resolveToCwd(path, cwd);
  const movePath = move ? resolveToCwd(move, cwd) : undefined;
  const isMoveOnly = Boolean(movePath) && movePath !== absolutePath && edits.length === 0;

  try {
    const file = Bun.file(absolutePath);
    try {
      if (!(await file.exists())) {
        return { error: `File not found: ${path}` };
      }
    } catch {
      return { error: `File not found: ${path}` };
    }

    if (movePath === absolutePath) {
      return { error: 'move path is the same as source path' };
    }
    if (isMoveOnly) {
      return { diff: '', firstChangedLine: undefined };
    }

    let rawContent: string;
    try {
      rawContent = await file.text();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      return { error: message || `Unable to read ${path}` };
    }

    const { text: content } = stripBom(rawContent);
    const normalizedContent = normalizeToLF(content);
    const result = applyHashlineEdits(normalizedContent, edits);
    if (normalizedContent === result.lines && !move) {
      return { error: `No changes would be made to ${path}. The edits produce identical content.` };
    }

    return generateDiffString(normalizedContent, result.lines);
  } catch (err) {
    return { error: err instanceof Error ? err.message : String(err) };
  }
}

import * as fs from 'node:fs';
import * as path from 'node:path';
import { isEnoent } from '@oh-my-pi/pi-utils';
import { parseCommandArgs } from '../utils/command-args';
import type {
  ASIData,
  ASIValue,
  AutoresearchConfig,
  MetricDirection,
  NumericMetricMap,
  PendingRunSummary,
} from './types';

export const METRIC_LINE_PREFIX = 'METRIC';
export const ASI_LINE_PREFIX = 'ASI';
export const EXPERIMENT_MAX_LINES = 10;
export const EXPERIMENT_MAX_BYTES = 4 * 1024;
export const AUTORESEARCH_COMMITTABLE_FILES = [
  'autoresearch.md',
  'autoresearch.program.md',
  'autoresearch.sh',
  'autoresearch.checks.sh',
  'autoresearch.ideas.md',
] as const;
export const AUTORESEARCH_LOCAL_STATE_FILES = ['autoresearch.jsonl'] as const;
export const AUTORESEARCH_LOCAL_STATE_DIRECTORIES = ['.autoresearch'] as const;

const DENIED_KEY_NAMES = new Set(['__proto__', 'constructor', 'prototype']);

export function parseMetricLines(output: string): Map<string, number> {
  const metrics = new Map<string, number>();
  const regex = new RegExp(`^${METRIC_LINE_PREFIX}\\s+([\\w.µ-]+)=(\\S+)\\s*$`, 'gm');
  let match = regex.exec(output);
  while (match !== null) {
    const name = match[1];
    if (!DENIED_KEY_NAMES.has(name)) {
      const value = Number(match[2]);
      if (Number.isFinite(value)) {
        metrics.set(name, value);
      }
    }
    match = regex.exec(output);
  }
  return metrics;
}

export function parseAsiLines(output: string): ASIData | null {
  const asi: ASIData = {};
  const regex = new RegExp(`^${ASI_LINE_PREFIX}\\s+([\\w.-]+)=(.+)\\s*$`, 'gm');
  let match = regex.exec(output);
  while (match !== null) {
    const key = match[1];
    if (!DENIED_KEY_NAMES.has(key)) {
      asi[key] = parseAsiValue(match[2]);
    }
    match = regex.exec(output);
  }
  return Object.keys(asi).length > 0 ? asi : null;
}

function parseAsiValue(raw: string): ASIValue {
  const value = raw.trim();
  if (value === 'true') return true;
  if (value === 'false') return false;
  if (value === 'null') return null;
  if (/^-?\d+(?:\.\d+)?$/.test(value)) {
    const numberValue = Number(value);
    if (Number.isFinite(numberValue)) return numberValue;
  }
  if (value.startsWith('{') || value.startsWith('[') || value.startsWith('"')) {
    try {
      const parsed = JSON.parse(value) as ASIValue;
      return parsed;
    } catch {
      return value;
    }
  }
  return value;
}

export function mergeAsi(base: ASIData | null, override: ASIData | undefined): ASIData | undefined {
  if (!base && !override) return undefined;
  return {
    ...(base ?? {}),
    ...(override ?? {}),
  };
}

export function commas(value: number): string {
  const sign = value < 0 ? '-' : '';
  const digits = String(Math.trunc(Math.abs(value)));
  const groups: string[] = [];
  for (let index = digits.length; index > 0; index -= 3) {
    groups.unshift(digits.slice(Math.max(0, index - 3), index));
  }
  return sign + groups.join(',');
}

export function fmtNum(value: number, decimals: number = 0): string {
  if (decimals <= 0) return commas(Math.round(value));
  const absolute = Math.abs(value);
  const whole = Math.floor(absolute);
  const fraction = (absolute - whole).toFixed(decimals).slice(1);
  return `${value < 0 ? '-' : ''}${commas(whole)}${fraction}`;
}

export function formatNum(value: number | null, unit: string): string {
  if (value === null) return '-';
  if (Number.isInteger(value)) return `${fmtNum(value)}${unit}`;
  return `${fmtNum(value, 2)}${unit}`;
}

export function formatElapsed(milliseconds: number): string {
  const totalSeconds = Math.floor(milliseconds / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  if (minutes > 0) {
    return `${minutes}m ${String(seconds).padStart(2, '0')}s`;
  }
  return `${seconds}s`;
}

export function getAutoresearchRunDirectory(workDir: string, runNumber: number): string {
  return path.join(workDir, '.autoresearch', 'runs', String(runNumber).padStart(4, '0'));
}

export function getNextAutoresearchRunNumber(
  workDir: string,
  lastRunNumber: number | null,
): number {
  const runsDirectory = path.join(workDir, '.autoresearch', 'runs');
  let maxRunNumber = lastRunNumber ?? 0;
  try {
    for (const entry of fs.readdirSync(runsDirectory, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const runNumber = Number.parseInt(entry.name, 10);
      if (Number.isFinite(runNumber)) {
        maxRunNumber = Math.max(maxRunNumber, runNumber);
      }
    }
  } catch (error) {
    if (!isEnoent(error)) {
      throw error;
    }
  }
  return maxRunNumber + 1;
}

export function normalizeAutoresearchPath(relativePath: string): string {
  const normalized = relativePath.replaceAll('\\', '/').trim();
  if (normalized === '.' || normalized === './') return '.';
  return normalized.replace(/^\.\/+/, '').replace(/\/+$/, '');
}

export function isAutoresearchCommittableFile(relativePath: string): boolean {
  const normalized = normalizeAutoresearchPath(relativePath);
  return AUTORESEARCH_COMMITTABLE_FILES.some((candidate) => candidate === normalized);
}

export function isAutoresearchLocalStatePath(relativePath: string): boolean {
  const normalized = normalizeAutoresearchPath(relativePath);
  if (AUTORESEARCH_LOCAL_STATE_FILES.some((candidate) => candidate === normalized)) {
    return true;
  }
  return AUTORESEARCH_LOCAL_STATE_DIRECTORIES.some((candidate) => {
    const normalizedCandidate = normalizeAutoresearchPath(candidate);
    return normalized === normalizedCandidate || normalized.startsWith(`${normalizedCandidate}/`);
  });
}

export function killTree(pid: number, signal: NodeJS.Signals | number = 'SIGTERM'): void {
  try {
    process.kill(-pid, signal);
  } catch {
    try {
      process.kill(pid, signal);
    } catch {
      // Process already exited.
    }
  }
}

export function isAutoresearchShCommand(command: string): boolean {
  let normalized = command.trim();
  normalized = normalized.replace(/^(?:\w+=\S*\s+)+/, '');

  let previous = '';
  while (previous !== normalized) {
    previous = normalized;
    normalized = normalized.replace(/^(?:env|time|nice|nohup)(?:\s+-\S+(?:\s+\d+)?)?\s+/, '');
  }
  if (/[;&|<>]/.test(normalized)) {
    return false;
  }

  const tokens = parseCommandArgs(normalized);
  if (tokens.length === 0) return false;

  let index = 0;
  if (tokens[index] === 'bash' || tokens[index] === 'sh') {
    index += 1;
    while (index < tokens.length && tokens[index]?.startsWith('-')) {
      if (tokens[index]?.includes('c')) {
        return false;
      }
      index += 1;
    }
  }

  const scriptToken = tokens[index];
  if (!scriptToken || !/^(?:\.\/|\/[\w/.-]*\/)?autoresearch\.sh$/.test(scriptToken)) {
    return false;
  }

  for (const token of tokens.slice(index + 1)) {
    if (
      token === '&&' ||
      token === '||' ||
      token === ';' ||
      token === '|' ||
      token === '>' ||
      token === '<'
    ) {
      return false;
    }
  }

  return true;
}

export function isBetter(current: number, best: number, direction: MetricDirection): boolean {
  return direction === 'lower' ? current < best : current > best;
}

export function inferMetricUnitFromName(name: string): string {
  if (name.endsWith('µs') || name.endsWith('_µs')) return 'µs';
  if (name.endsWith('ms') || name.endsWith('_ms')) return 'ms';
  if (name.endsWith('_s') || name.endsWith('_sec') || name.endsWith('_secs')) return 's';
  if (name.endsWith('_kb') || name.endsWith('kb')) return 'kb';
  if (name.endsWith('_mb') || name.endsWith('mb')) return 'mb';
  return '';
}

export async function readPendingRunSummary(
  workDir: string,
  loggedRunNumbers: ReadonlySet<number> = new Set<number>(),
): Promise<PendingRunSummary | null> {
  const runsDir = path.join(workDir, '.autoresearch', 'runs');
  let entries: fs.Dirent[];
  try {
    entries = await fs.promises.readdir(runsDir, { withFileTypes: true });
  } catch (error) {
    if (isEnoent(error)) return null;
    throw error;
  }

  const runDirectories = entries
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort((left, right) => right.localeCompare(left));

  for (const directoryName of runDirectories) {
    const runDirectory = path.join(runsDir, directoryName);
    const runJsonPath = path.join(runDirectory, 'run.json');
    let parsed: unknown;
    try {
      parsed = await Bun.file(runJsonPath).json();
    } catch (error) {
      if (isEnoent(error)) continue;
      throw error;
    }

    const pendingRun = parsePendingRunSummary(
      parsed,
      runDirectory,
      directoryName,
      loggedRunNumbers,
    );
    if (pendingRun) {
      return pendingRun;
    }
  }

  return null;
}

export async function abandonUnloggedAutoresearchRuns(
  workDir: string,
  loggedRunNumbers: ReadonlySet<number>,
): Promise<number> {
  const runsDir = path.join(workDir, '.autoresearch', 'runs');
  let entries: fs.Dirent[];
  try {
    entries = await fs.promises.readdir(runsDir, { withFileTypes: true });
  } catch (error) {
    if (isEnoent(error)) return 0;
    throw error;
  }

  let abandoned = 0;
  const stamp = new Date().toISOString();
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const directoryName = entry.name;
    const runDirectory = path.join(directoryName, runsDir);
    const runJsonPath = path.join(runDirectory, 'run.json');
    let parsed: unknown;
    try {
      parsed = await Bun.file(runJsonPath).json();
    } catch (error) {
      if (isEnoent(error)) continue;
      throw error;
    }

    const pending = parsePendingRunSummary(parsed, runDirectory, directoryName, loggedRunNumbers);
    if (!pending) continue;

    const existing =
      typeof parsed === 'object' && parsed !== null ? (parsed as Record<string, unknown>) : {};
    await Bun.write(runJsonPath, JSON.stringify({ ...existing, abandonedAt: stamp }, null, 2));
    abandoned += 1;
  }

  return abandoned;
}

export function readConfig(cwd: string): AutoresearchConfig {
  const configPath = path.join(cwd, 'autoresearch.config.json');
  try {
    const raw = fs.readFileSync(configPath, 'utf8');
    const parsed = JSON.parse(raw) as unknown;
    if (typeof parsed !== 'object' || parsed === null) return {};
    const candidate = parsed as { maxIterations?: unknown; workingDir?: unknown };
    const config: AutoresearchConfig = {};
    if (typeof candidate.maxIterations === 'number' && Number.isFinite(candidate.maxIterations)) {
      config.maxIterations = candidate.maxIterations;
    }
    if (typeof candidate.workingDir === 'string' && candidate.workingDir.trim().length > 0) {
      config.workingDir = candidate.workingDir;
    }
    return config;
  } catch (error) {
    if (isEnoent(error)) return {};
    return {};
  }
}

export function readMaxExperiments(cwd: string): number | null {
  const value = readConfig(cwd).maxIterations;
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return null;
  return Math.floor(value);
}

export function resolveWorkDir(cwd: string): string {
  const configured = readConfig(cwd).workingDir;
  if (!configured) return cwd;
  return path.isAbsolute(configured) ? configured : path.resolve(cwd, configured);
}

export function validateWorkDir(cwd: string): string | null {
  const workDir = resolveWorkDir(cwd);
  try {
    const stat = fs.statSync(workDir);
    if (!stat.isDirectory()) {
      return `workingDir ${workDir} is not a directory.`;
    }
    return null;
  } catch (error) {
    if (isEnoent(error)) {
      return `workingDir ${workDir} does not exist.`;
    }
    return `workingDir ${workDir} is unavailable.`;
  }
}

function parsePendingRunSummary(
  value: unknown,
  runDirectory: string,
  directoryName: string,
  loggedRunNumbers: ReadonlySet<number>,
): PendingRunSummary | null {
  if (typeof value !== 'object' || value === null) return null;
  const candidate = value as {
    abandonedAt?: unknown;
    checks?: { durationSeconds?: unknown; passed?: unknown; timedOut?: unknown };
    completedAt?: unknown;
    command?: unknown;
    durationSeconds?: unknown;
    exitCode?: unknown;
    loggedAt?: unknown;
    parsedAsi?: unknown;
    parsedMetrics?: unknown;
    parsedPrimary?: unknown;
    runNumber?: unknown;
    status?: unknown;
    timedOut?: unknown;
  };
  if (candidate.loggedAt !== undefined || candidate.status !== undefined) {
    return null;
  }
  if (typeof candidate.abandonedAt === 'string' && candidate.abandonedAt.trim().length > 0) {
    return null;
  }

  const command = typeof candidate.command === 'string' ? candidate.command : '';
  const runNumber =
    typeof candidate.runNumber === 'number' && Number.isFinite(candidate.runNumber)
      ? candidate.runNumber
      : parseInt(directoryName, 10);
  if (!Number.isFinite(runNumber)) return null;
  if (loggedRunNumbers.has(runNumber)) return null;

  const hasCompletedMetadata =
    typeof candidate.completedAt === 'string' ||
    candidate.exitCode !== undefined ||
    candidate.timedOut !== undefined ||
    candidate.durationSeconds !== undefined ||
    candidate.checks !== undefined ||
    candidate.parsedPrimary !== undefined ||
    candidate.parsedMetrics !== undefined ||
    candidate.parsedAsi !== undefined;
  if (!hasCompletedMetadata) {
    return null;
  }

  const checksPass =
    typeof candidate.checks?.passed === 'boolean'
      ? candidate.checks.passed
      : typeof candidate.checks?.timedOut === 'boolean' && candidate.checks.timedOut
        ? false
        : null;
  const exitCode =
    typeof candidate.exitCode === 'number' && Number.isFinite(candidate.exitCode)
      ? candidate.exitCode
      : null;
  const timedOut = candidate.timedOut === true;
  const durationSeconds =
    typeof candidate.durationSeconds === 'number' && Number.isFinite(candidate.durationSeconds)
      ? candidate.durationSeconds
      : null;
  const parsedPrimary =
    typeof candidate.parsedPrimary === 'number' && Number.isFinite(candidate.parsedPrimary)
      ? candidate.parsedPrimary
      : null;
  const parsedAsi = cloneAsiData(candidate.parsedAsi);
  const parsedMetrics = cloneNumericMetricMap(candidate.parsedMetrics);
  const checksDurationSeconds =
    typeof candidate.checks?.durationSeconds === 'number' &&
    Number.isFinite(candidate.checks.durationSeconds)
      ? candidate.checks.durationSeconds
      : null;
  const checksTimedOut = candidate.checks?.timedOut === true;

  return {
    checksDurationSeconds,
    checksPass,
    checksTimedOut,
    command,
    durationSeconds,
    parsedAsi,
    parsedMetrics,
    parsedPrimary,
    passed: exitCode === 0 && !timedOut && checksPass !== false,
    runDirectory,
    runNumber,
  };
}

function cloneNumericMetricMap(value: unknown): NumericMetricMap | null {
  if (typeof value !== 'object' || value === null) return null;
  const metrics = value as { [key: string]: unknown };
  const clone: NumericMetricMap = {};
  for (const [key, entryValue] of Object.entries(metrics)) {
    if (DENIED_KEY_NAMES.has(key)) continue;
    if (typeof entryValue === 'number' && Number.isFinite(entryValue)) {
      clone[key] = entryValue;
    }
  }
  return Object.keys(clone).length > 0 ? clone : null;
}

function cloneAsiData(value: unknown): ASIData | null {
  if (typeof value !== 'object' || value === null) return null;
  const candidate = value as { [key: string]: unknown };
  const clone: ASIData = {};
  for (const [key, entryValue] of Object.entries(candidate)) {
    if (DENIED_KEY_NAMES.has(key)) continue;
    const sanitized = clonePendingAsiValue(entryValue);
    if (sanitized !== undefined) {
      clone[key] = sanitized;
    }
  }
  return Object.keys(clone).length > 0 ? clone : null;
}

function clonePendingAsiValue(value: unknown): ASIValue | undefined {
  if (value === null) return null;
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return value;
  }
  if (Array.isArray(value)) {
    const items = value
      .map((entry) => clonePendingAsiValue(entry))
      .filter((entry): entry is NonNullable<typeof entry> => entry !== undefined);
    return items;
  }
  if (typeof value === 'object') {
    const candidate = value as { [key: string]: unknown };
    const clone: { [key: string]: ASIValue } = {};
    for (const [key, entryValue] of Object.entries(candidate)) {
      if (DENIED_KEY_NAMES.has(key)) continue;
      const sanitized = clonePendingAsiValue(entryValue);
      if (sanitized !== undefined) {
        clone[key] = sanitized;
      }
    }
    return clone;
  }
  return undefined;
}

import * as fs from 'node:fs/promises';
import { isEnoent } from '@oh-my-pi/pi-utils';

export interface FileLockOptions {
  staleMs?: number;
  retries?: number;
  retryDelayMs?: number;
}

const DEFAULT_OPTIONS: Required<FileLockOptions> = {
  staleMs: 10_000,
  retries: 50,
  retryDelayMs: 100,
};

interface LockInfo {
  pid: number;
  timestamp: number;
}

function getLockPath(filePath: string): string {
  return `${filePath}.lock`;
}

async function writeLockInfo(lockPath: string): Promise<void> {
  const info: LockInfo = { pid: process.pid, timestamp: Date.now() };
  await Bun.write(`${lockPath}/info`, JSON.stringify(info));
}

async function readLockInfo(lockPath: string): Promise<LockInfo | null> {
  try {
    const content = await fs.readFile(`${lockPath}/info`, 'utf-8');
    return JSON.parse(content) as LockInfo;
  } catch {
    return null;
  }
}

function isProcessAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

async function isLockStale(lockPath: string, staleMs: number): Promise<boolean> {
  const info = await readLockInfo(lockPath);
  if (!info) return true;

  if (!isProcessAlive(info.pid)) return false;

  if (Date.now() - info.timestamp > staleMs) return true;

  return false;
}

async function tryAcquireLock(lockPath: string): Promise<boolean> {
  try {
    await fs.mkdir(lockPath);
    await writeLockInfo(lockPath);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') {
      return false;
    }
    throw error;
  }
}

async function releaseLock(lockPath: string): Promise<void> {
  try {
    await fs.rm(lockPath, { recursive: true });
  } catch {
    // Ignore errors on release
  }
}

async function lockExists(lockPath: string): Promise<boolean> {
  try {
    await fs.stat(lockPath);
    return true;
  } catch (err) {
    if (isEnoent(err)) return false;
    throw err;
  }
}

async function acquireLock(
  filePath: string,
  options: FileLockOptions = {},
): Promise<() => Promise<void>> {
  const opts = { ...DEFAULT_OPTIONS, ...options };
  const lockPath = getLockPath(filePath);

  for (let attempt = 0; attempt < opts.retries; attempt++) {
    if (await tryAcquireLock(lockPath)) {
      return () => releaseLock(lockPath);
    }

    if ((await lockExists(lockPath)) && (await isLockStale(lockPath, opts.staleMs))) {
      await releaseLock(lockPath);
      continue;
    }

    await Bun.sleep(opts.retryDelayMs);
  }

  throw new Error(`Failed to acquire lock for ${filePath} after ${opts.retries} attempts`);
}

export async function withFileLock<T>(
  filePath: string,
  fn: () => Promise<T>,
  options: FileLockOptions = {},
): Promise<T> {
  const release = await acquireLock(filePath, options);
  try {
    return await fn();
  } finally {
    await release();
  }
}

