import {
  type GenerateContentConfig,
  type GenerateContentParameters,
  GoogleGenAI,
  type ThinkingConfig,
} from '@google/genai';
import { calculateCost } from '../models';
import { getEnvApiKey } from '../stream';
import type {
  Api,
  AssistantMessage,
  Context,
  Model,
  StreamFunction,
  StreamOptions,
  TextContent,
  ThinkingContent,
  ToolCall,
} from '../types';
import { AssistantMessageEventStream } from '../utils/event-stream';
import { finalizeErrorMessage, type RawHttpRequestDump } from '../utils/http-inspector';
import type { GoogleThinkingLevel } from './google-gemini-cli';
import {
  convertMessages,
  convertTools,
  isThinkingPart,
  mapStopReason,
  mapToolChoice,
  retainThoughtSignature,
} from './google-shared';

export interface GoogleOptions extends StreamOptions {
  toolChoice?: 'auto' | 'none' | 'any';
  thinking?: {
    enabled: boolean;
    budgetTokens?: number; // -1 for dynamic, 0 to disable
    level?: GoogleThinkingLevel;
  };
}

interface GoogleSamplingConfig extends GenerateContentConfig {
  topP?: number;
  topK?: number;
  minP?: number;
  presencePenalty?: number;
  repetitionPenalty?: number;
}

// Counter for generating unique tool call IDs
let toolCallCounter = 0;

export const streamGoogle: StreamFunction<'google-generative-ai'> = (
  model: Model<'google-generative-ai'>,
  context: Context,
  options?: GoogleOptions,
): AssistantMessageEventStream => {
  const stream = new AssistantMessageEventStream();

  (async () => {
    const startTime = Date.now();
    let firstTokenTime: number | undefined;

    const output: AssistantMessage = {
      role: 'assistant',
      content: [],
      api: 'google-generative-ai' as Api,
      provider: model.provider,
      model: model.id,
      usage: {
        input: 0,
        output: 0,
        cacheRead: 0,
        cacheWrite: 0,
        totalTokens: 0,
        cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
      },
      stopReason: 'stop',
      timestamp: Date.now(),
    };
    let rawRequestDump: RawHttpRequestDump | undefined;

    try {
      const apiKey = options?.apiKey || getEnvApiKey(model.provider);
      const client = createClient(model, apiKey);
      const params = buildParams(model, context, options);
      options?.onPayload?.(params);
      rawRequestDump = {
        provider: model.provider,
        api: output.api,
        model: model.id,
        method: 'POST',
        url: model.baseUrl
          ? `${model.baseUrl}/models/${model.id}:streamGenerateContent`
          : undefined,
        body: params,
      };
      const googleStream = await client.models.generateContentStream(params);

      stream.push({ type: 'start', partial: output });
      let currentBlock: TextContent | ThinkingContent | null = null;
      const blocks = output.content;
      const blockIndex = () => blocks.length - 1;
      for await (const chunk of googleStream) {
        const candidate = chunk.candidates?.[0];
        if (candidate?.content?.parts) {
          for (const part of candidate.content.parts) {
            if (part.text !== undefined) {
              const isThinking = isThinkingPart(part);
              if (firstTokenTime) firstTokenTime = Date.now();
              if (
                !currentBlock ||
                (isThinking && currentBlock.type !== 'thinking') ||
                (!isThinking && currentBlock.type !== 'text')
              ) {
                if (currentBlock) {
                  if (currentBlock.type === 'text') {
                    stream.push({
                      type: 'text_end',
                      contentIndex: blocks.length - 1,
                      content: currentBlock.text,
                      partial: output,
                    });
                  } else {
                    stream.push({
                      type: 'thinking_end',
                      contentIndex: blockIndex(),
                      content: currentBlock.thinking,
                      partial: output,
                    });
                  }
                }
                if (isThinking) {
                  currentBlock = { type: 'thinking', thinking: '', thinkingSignature: undefined };
                  output.content.push(currentBlock);
                  stream.push({
                    type: 'thinking_start',
                    contentIndex: blockIndex(),
                    partial: output,
                  });
                } else {
                  currentBlock = { type: 'text', text: '' };
                  output.content.push(currentBlock);
                  stream.push({ type: 'text_start', contentIndex: blockIndex(), partial: output });
                }
              }
              if (currentBlock.type === 'thinking') {
                currentBlock.thinking += part.text;
                currentBlock.thinkingSignature = retainThoughtSignature(
                  currentBlock.thinkingSignature,
                  part.thoughtSignature,
                );
                stream.push({
                  type: 'thinking_delta',
                  contentIndex: blockIndex(),
                  delta: part.text,
                  partial: output,
                });
              } else {
                currentBlock.text += part.text;
                stream.push({
                  type: 'text_delta',
                  contentIndex: blockIndex(),
                  delta: part.text,
                  partial: output,
                });
              }
            }

            if (part.functionCall) {
              if (currentBlock) {
                if (currentBlock.type === 'text') {
                  stream.push({
                    type: 'text_end',
                    contentIndex: blockIndex(),
                    content: currentBlock.text,
                    partial: output,
                  });
                } else {
                  stream.push({
                    type: 'thinking_end',
                    contentIndex: blockIndex(),
                    content: currentBlock.thinking,
                    partial: output,
                  });
                }
                currentBlock = null;
              }

              // Generate unique ID if not provided or if it's a duplicate
              const providedId = part.functionCall.id;
              const needsNewId =
                !providedId ||
                output.content.some((b) => b.type === 'toolCall' && b.id === providedId);
              const toolCallId = needsNewId
                ? `${part.functionCall.name}_${Date.now()}_${++toolCallCounter}`
                : providedId;

              const toolCall: ToolCall = {
                type: 'toolCall',
                id: toolCallId,
                name: part.functionCall.name || '',
                arguments: (part.functionCall.args ?? {}) as Record<string, any>,
                ...(part.thoughtSignature && { thoughtSignature: part.thoughtSignature }),
              };

              output.content.push(toolCall);
              stream.push({ type: 'toolcall_start', contentIndex: blockIndex(), partial: output });
              stream.push({
                type: 'toolcall_delta',
                contentIndex: blockIndex(),
                delta: JSON.stringify(toolCall.arguments),
                partial: output,
              });
              stream.push({
                type: 'toolcall_end',
                contentIndex: blockIndex(),
                toolCall,
                partial: output,
              });
            }
          }
        }

        if (candidate?.finishReason) {
          output.stopReason = mapStopReason(candidate.finishReason);
          if (output.content.some((b) => b.type === 'toolCall')) {
            output.stopReason = 'toolUse';
          }
        }

        if (chunk.usageMetadata) {
          // promptTokenCount includes cachedContentTokenCount when cached content is used.
          // Subtract to get non-cached input, matching the OpenAI convention where
          // input = uncached prompt tokens and cacheRead = cached tokens so that
          // input + cacheRead = total prompt tokens (no double-counting).
          // Ref: https://ai.google.dev/api/generate-content#v1beta.GenerateContentResponse.UsageMetadata
          const cachedTokens = chunk.usageMetadata.cachedContentTokenCount || 0;
          output.usage = {
            input: (chunk.usageMetadata.promptTokenCount || 0) - cachedTokens,
            output:
              (chunk.usageMetadata.candidatesTokenCount || 0) +
              (chunk.usageMetadata.thoughtsTokenCount || 0),
            cacheRead: cachedTokens,
            cacheWrite: 0,
            totalTokens: chunk.usageMetadata.totalTokenCount || 0,
            cost: {
              input: 0,
              output: 0,
              cacheRead: 0,
              cacheWrite: 0,
              total: 0,
            },
          };
          calculateCost(model, output.usage);
        }
      }

      if (currentBlock) {
        if (currentBlock.type === 'text') {
          stream.push({
            type: 'text_end',
            contentIndex: blockIndex(),
            content: currentBlock.text,
            partial: output,
          });
        } else {
          stream.push({
            type: 'thinking_end',
            contentIndex: blockIndex(),
            content: currentBlock.thinking,
            partial: output,
          });
        }
      }

      if (options?.signal?.aborted) {
        throw new Error('Request was aborted');
      }

      if (output.stopReason === 'aborted' || output.stopReason === 'error') {
        throw new Error('An unknown error occurred');
      }

      output.duration = Date.now() - startTime;
      if (firstTokenTime) output.ttft = firstTokenTime - startTime;
      stream.push({ type: 'done', reason: output.stopReason, message: output });
      stream.end();
    } catch (error) {
      // Remove internal index property used during streaming
      for (const block of output.content) {
        if ('index' in block) {
          delete (block as { index?: number }).index;
        }
      }
      output.stopReason = options?.signal?.aborted ? 'aborted' : 'error';
      output.errorMessage = await finalizeErrorMessage(error, rawRequestDump);
      output.duration = Date.now() - startTime;
      if (firstTokenTime) output.ttft = firstTokenTime - startTime;
      stream.push({ type: 'error', reason: output.stopReason, error: output });
      stream.end();
    }
  })();

  return stream;
};

function createClient(model: Model<'google-generative-ai'>, apiKey?: string): GoogleGenAI {
  const httpOptions: { baseUrl?: string; apiVersion?: string; headers?: Record<string, string> } =
    {};
  if (model.baseUrl) {
    httpOptions.baseUrl = model.baseUrl;
    httpOptions.apiVersion = ''; // baseUrl already includes version path, don't append
  }
  if (model.headers) {
    httpOptions.headers = model.headers;
  }

  return new GoogleGenAI({
    apiKey,
    httpOptions: Object.keys(httpOptions).length > 0 ? httpOptions : undefined,
  });
}

function buildParams(
  model: Model<'google-generative-ai'>,
  context: Context,
  options: GoogleOptions = {},
): GenerateContentParameters {
  const contents = convertMessages(model, context);

  const generationConfig: GoogleSamplingConfig = {};
  if (options.temperature !== undefined) {
    generationConfig.temperature = options.temperature;
  }
  if (options.maxTokens !== undefined) {
    generationConfig.maxOutputTokens = options.maxTokens;
  }
  if (options.topP !== undefined) {
    generationConfig.topP = options.topP;
  }
  if (options.topK !== undefined) {
    generationConfig.topK = options.topK;
  }
  if (options.minP !== undefined) {
    generationConfig.minP = options.minP;
  }
  if (options.presencePenalty !== undefined) {
    generationConfig.presencePenalty = options.presencePenalty;
  }
  if (options.repetitionPenalty !== undefined) {
    generationConfig.repetitionPenalty = options.repetitionPenalty;
  }

  const config: GenerateContentConfig = {
    ...(Object.keys(generationConfig).length > 0 && generationConfig),
    ...(context.systemPrompt && { systemInstruction: context.systemPrompt.toWellFormed() }),
    ...(context.tools && context.tools.length > 0 && { tools: convertTools(context.tools, model) }),
  };

  if (context.tools && context.tools.length > 0 && options.toolChoice) {
    config.toolConfig = {
      functionCallingConfig: {
        mode: mapToolChoice(options.toolChoice),
      },
    };
  } else {
    config.toolConfig = undefined;
  }

  if (options.thinking?.enabled && model.reasoning) {
    const cfg: ThinkingConfig = { includeThoughts: true };
    if (options.thinking.level !== undefined) {
      // Cast to any since our GoogleThinkingLevel mirrors Google's ThinkingLevel enum values
      cfg.thinkingLevel = options.thinking.level as any;
    } else if (options.thinking.budgetTokens !== undefined) {
      cfg.thinkingBudget = options.thinking.budgetTokens;
    }
    config.thinkingConfig = cfg;
  }

  if (options.signal) {
    if (options.signal.aborted) {
      throw new Error('Request aborted');
    }
    config.abortSignal = options.signal;
  }

  const params: GenerateContentParameters = {
    model: model.id,
    contents,
    config,
  };

  return params;
}

