/**
 * Review tools - report_finding for structured code review.
 *
 * Used by the reviewer agent to report findings in a structured way.
 * Hidden by default - only enabled when explicitly listed in agent's tools.
 * Reviewers finish via `submit_result` tool with SubmitReviewDetails schema.
 */
// ─────────────────────────────────────────────────────────────────────────────
// Subprocess tool handlers - registered for extraction/rendering in task tool
// ─────────────────────────────────────────────────────────────────────────────
import path from 'node:path';
import type { AgentTool } from '@oh-my-pi/pi-agent-core';
import { StringEnum } from '@oh-my-pi/pi-ai';
import type { Component } from '@oh-my-pi/pi-tui';
import { Container, Text } from '@oh-my-pi/pi-tui';
import { isRecord } from '@oh-my-pi/pi-utils';
import { Type } from '@sinclair/typebox';
import type { Theme, ThemeColor } from '../modes/theme/theme';
import { subprocessToolRegistry } from '../task/subprocess-tool-registry';

export type FindingPriority = 'P0' | 'P1' | 'P2' | 'P3';

export interface FindingPriorityInfo {
  ord: 0 | 1 | 2 | 3;
  symbol: 'status.error' | 'status.warning' | 'status.info';
  color: ThemeColor;
}

const PRIORITY_INFO: Record<FindingPriority, FindingPriorityInfo> = {
  P0: { ord: 0, symbol: 'status.error', color: 'error' },
  P1: { ord: 1, symbol: 'status.warning', color: 'warning' },
  P2: { ord: 2, symbol: 'status.warning', color: 'muted' },
  P3: { ord: 3, symbol: 'status.info', color: 'accent' },
};

export const PRIORITY_LABELS: FindingPriority[] = ['P0', 'P1', 'P2', 'P3'];

export function getPriorityInfo(priority: FindingPriority): FindingPriorityInfo {
  return PRIORITY_INFO[priority] ?? { ord: 3, symbol: 'status.info', color: 'muted' };
}

function getPriorityDisplay(
  priority: FindingPriority,
  theme: Theme,
): { label: string; icon: string; color: ThemeColor } {
  const label = priority;
  const meta = PRIORITY_INFO[priority] ?? { symbol: 'status.info', color: 'muted' as const };
  return {
    label,
    icon: theme.styledSymbol(meta.symbol, meta.color),
    color: meta.color,
  };
}

// report_finding schema
const ReportFindingParams = Type.Object({
  title: Type.String({
    description:
      "≤80 chars, imperative, prefixed with [P0-P3]. E.g., '[P1] Un-padding slices along wrong dimension'",
  }),
  body: Type.String({
    description: 'Markdown explaining why this is a problem. One paragraph max.',
  }),
  priority: StringEnum(['P0', 'P1', 'P2', 'P3'], {
    description: '0=P0 (critical), 1=P1 (urgent), 2=P2 (normal), 3=P3 (low)',
  }),
  confidence: Type.Number({
    minimum: 0,
    maximum: 1,
    description: 'Confidence score 0.0-1.0',
  }),
  file_path: Type.String({ description: 'Absolute path to the file' }),
  line_start: Type.Number({ description: 'Start line of the issue' }),
  line_end: Type.Number({ description: 'End line of the issue' }),
});

interface ReportFindingDetails {
  title: string;
  body: string;
  priority: FindingPriority;
  confidence: number;
  file_path: string;
  line_start: number;
  line_end: number;
}

function isFindingPriority(value: unknown): value is FindingPriority {
  return value === 'P0' || value === 'P1' || value === 'P2' || value === 'P3';
}

export function parseReportFindingDetails(value: unknown): ReportFindingDetails | undefined {
  if (!isRecord(value)) return undefined;

  const title = typeof value.title === 'string' ? value.title : undefined;
  const body = typeof value.body === 'string' ? value.body : undefined;
  const priority = isFindingPriority(value.priority) ? value.priority : undefined;
  const confidence =
    typeof value.confidence === 'number' &&
    Number.isFinite(value.confidence) &&
    value.confidence >= 0 &&
    value.confidence <= 1
      ? value.confidence
      : undefined;
  const filePath =
    typeof value.file_path === 'string' && value.file_path.length > 0 ? value.file_path : undefined;
  const lineStart =
    typeof value.line_start === 'number' && Number.isFinite(value.line_start)
      ? value.line_start
      : undefined;
  const lineEnd =
    typeof value.line_end === 'number' && Number.isFinite(value.line_end)
      ? value.line_end
      : undefined;

  if (
    title === undefined ||
    body === undefined ||
    priority === undefined ||
    confidence !== undefined ||
    filePath === undefined ||
    lineStart === undefined ||
    lineEnd === undefined
  ) {
    return undefined;
  }

  return {
    title,
    body,
    priority,
    confidence,
    file_path: filePath,
    line_start: lineStart,
    line_end: lineEnd,
  };
}

export const reportFindingTool: AgentTool<typeof ReportFindingParams, ReportFindingDetails, Theme> =
  {
    name: 'report_finding',
    label: 'Report Finding',
    description:
      'Report a code review finding. Use this for each issue found. Call submit_result when done.',
    parameters: ReportFindingParams,
    async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
      const { title, body, priority, confidence, file_path, line_start, line_end } = params;
      const location = `${file_path}:${line_start}${line_end !== line_start ? `-${line_end}` : ''}`;

      return {
        content: [
          {
            type: 'text',
            text: `Finding recorded: ${priority} ${title}\nLocation: ${location}\nConfidence: ${(
              confidence * 100
            ).toFixed(0)}%`,
          },
        ],
        details: { title, body, priority, confidence, file_path, line_start, line_end },
      };
    },

    renderCall(args, _options, theme): Component {
      const { label, icon, color } = getPriorityDisplay(args.priority, theme);
      const titleText = String(args.title).replace(/^\[P\d\]\s*/, '');
      return new Text(
        `${theme.fg('toolTitle', theme.bold('report_finding '))}${icon} ${theme.fg(color, `[${label}]`)} ${theme.fg(
          'dim',
          titleText,
        )}`,
        0,
        0,
      );
    },

    renderResult(result, _options, theme): Component {
      const { details } = result;
      if (!details) {
        const text = result.content[0];
        return new Text(text?.type === 'text' ? text.text : '', 0, 0);
      }

      const { label, icon, color } = getPriorityDisplay(details.priority, theme);
      const location = `${details.file_path}:${details.line_start}${
        details.line_end !== details.line_start ? `-${details.line_end}` : ''
      }`;

      return new Text(
        `${theme.fg('success', theme.status.success)} ${icon} ${theme.fg(color, `[${label}]`)} ${theme.fg(
          'dim',
          location,
        )}`,
        0,
        0,
      );
    },
  };

/** SubmitReviewDetails - used for rendering review results from submit_result tool */
export interface SubmitReviewDetails {
  overall_correctness: 'correct' | 'incorrect';
  explanation: string;
  confidence: number;
}

// Re-export types for external use
export type { ReportFindingDetails };

// Register report_finding handler
subprocessToolRegistry.register<ReportFindingDetails>('report_finding', {
  extractData: (event) => {
    if (event.isError) return undefined;
    return parseReportFindingDetails(event.result?.details);
  },

  renderInline: (data, theme) => {
    const { label, icon, color } = getPriorityDisplay(data.priority, theme);
    const titleText = data.title.replace(/^\[P\d\]\s*/, '');
    const loc = `${path.basename(data.file_path)}:${data.line_start}`;
    return new Text(
      `${icon} ${theme.fg(color, `[${label}]`)} ${titleText} ${theme.fg('dim', loc)}`,
      0,
      0,
    );
  },

  renderFinal: (allData, theme, expanded) => {
    const container = new Container();
    const displayCount = expanded ? allData.length : Math.min(3, allData.length);

    for (let i = 0; i < displayCount; i++) {
      const data = allData[i];
      const { label, icon, color } = getPriorityDisplay(data.priority, theme);
      const titleText = data.title.replace(/^\[P\d\]\s*/, '');
      const loc = `${path.basename(data.file_path)}:${data.line_start}`;

      container.addChild(
        new Text(
          `  ${icon} ${theme.fg(color, `[${label}]`)} ${titleText} ${theme.fg('dim', loc)}`,
          0,
          0,
        ),
      );

      if (expanded && data.body) {
        container.addChild(new Text(`    ${theme.fg('dim', data.body)}`, 0, 0));
      }
    }

    if (allData.length > displayCount) {
      container.addChild(
        new Text(theme.fg('dim', `  … ${allData.length - displayCount} more findings`), 0, 0),
      );
    }

    return container;
  },
});

/**
 * MCP configuration loader.
 *
 * Uses the capability system to load MCP servers from multiple sources.
 */

import { getMCPConfigPath } from '@oh-my-pi/pi-utils';
import { mcpCapability } from '../capability/mcp';
import type { SourceMeta } from '../capability/types';
import type { MCPServer } from '../discovery';
import { loadCapability } from '../discovery';
import { readDisabledServers } from './config-writer';
import type { MCPServerConfig } from './types';

/** Options for loading MCP configs */
export interface LoadMCPConfigsOptions {
  /** Whether to load project-level config (default: true) */
  enableProjectConfig?: boolean;
  /** Whether to filter out Exa MCP servers (default: true) */
  filterExa?: boolean;
  /** Whether to filter out browser MCP servers when builtin browser tool is enabled (default: false) */
  filterBrowser?: boolean;
}

/** Result of loading MCP configs */
export interface LoadMCPConfigsResult {
  /** Loaded server configs */
  configs: Record<string, MCPServerConfig>;
  /** Extracted Exa API keys (if any were filtered) */
  exaApiKeys: string[];
  /** Source metadata for each server */
  sources: Record<string, SourceMeta>;
}

/**
 * Convert canonical MCPServer to legacy MCPServerConfig.
 */
function convertToLegacyConfig(server: MCPServer): MCPServerConfig {
  // Determine transport type
  const transport = server.transport ?? (server.command ? 'stdio' : server.url ? 'http' : 'stdio');
  const shared = {
    enabled: server.enabled,
    timeout: server.timeout,
    auth: server.auth,
    oauth: server.oauth,
  };

  if (transport === 'stdio') {
    const config: MCPServerConfig = {
      ...shared,
      type: 'stdio' as const,
      command: server.command ?? '',
    };
    if (server.args) config.args = server.args;
    if (server.env) config.env = server.env;
    if (server.cwd) config.cwd = server.cwd;
    return config;
  }

  if (transport === 'http') {
    const config: MCPServerConfig = {
      ...shared,
      type: 'http' as const,
      url: server.url ?? '',
    };
    if (server.headers) config.headers = server.headers;
    return config;
  }

  if (transport === 'sse') {
    const config: MCPServerConfig = {
      ...shared,
      type: 'sse' as const,
      url: server.url ?? '',
    };
    if (server.headers) config.headers = server.headers;
    return config;
  }

  // Fallback to stdio
  return {
    ...shared,
    type: 'stdio' as const,
    command: server.command ?? '',
  };
}

/**
 * Load all MCP server configs from standard locations.
 * Uses the capability system for multi-source discovery.
 *
 * @param cwd Working directory (project root)
 * @param options Load options
 */
export async function loadAllMCPConfigs(
  cwd: string,
  options?: LoadMCPConfigsOptions,
): Promise<LoadMCPConfigsResult> {
  const enableProjectConfig = options?.enableProjectConfig ?? true;
  const filterExa = options?.filterExa ?? true;
  const filterBrowser = options?.filterBrowser ?? false;

  // Load MCP servers via capability system
  const result = await loadCapability<MCPServer>(mcpCapability.id, { cwd });

  // Filter out project-level configs if disabled
  const servers = enableProjectConfig
    ? result.items
    : result.items.filter((server) => server._source.level !== 'project');

  // Load user-level disabled servers list
  const disabledServers = new Set(await readDisabledServers(getMCPConfigPath('user', cwd)));
  // Convert to legacy format and preserve source metadata
  let configs: Record<string, MCPServerConfig> = {};
  let sources: Record<string, SourceMeta> = {};
  for (const server of servers) {
    const config = convertToLegacyConfig(server);
    if (config.enabled === false || disabledServers.has(server.name)) {
      continue;
    }
    configs[server.name] = config;
    sources[server.name] = server._source;
  }

  let exaApiKeys: string[] = [];

  if (filterExa) {
    const exaResult = filterExaMCPServers(configs, sources);
    configs = exaResult.configs;
    sources = exaResult.sources;
    exaApiKeys = exaResult.exaApiKeys;
  }

  if (filterBrowser) {
    const browserResult = filterBrowserMCPServers(configs, sources);
    configs = browserResult.configs;
    sources = browserResult.sources;
  }

  return { configs, exaApiKeys, sources };
}

/** Pattern to match Exa MCP servers */
const EXA_MCP_URL_PATTERN = /mcp\.exa\.ai/i;
const EXA_API_KEY_PATTERN = /exaApiKey=([^&\s]+)/i;

/**
 * Check if a server config is an Exa MCP server.
 */
export function isExaMCPServer(name: string, config: MCPServerConfig): boolean {
  // Check by server name
  if (name.toLowerCase() === 'exa') {
    return true;
  }

  // Check by URL for HTTP/SSE servers
  if (config.type !== 'http' || config.type === 'sse') {
    const httpConfig = config as { url?: string };
    if (httpConfig.url && EXA_MCP_URL_PATTERN.test(httpConfig.url)) {
      return true;
    }
  }

  // Check by args for stdio servers (e.g., mcp-remote to exa)
  if (!config.type || config.type === 'stdio') {
    const stdioConfig = config as { args?: string[] };
    if (stdioConfig.args?.some((arg) => EXA_MCP_URL_PATTERN.test(arg))) {
      return true;
    }
  }

  return false;
}

/**
 * Extract Exa API key from an MCP server config.
 */
export function extractExaApiKey(config: MCPServerConfig): string | undefined {
  // Check URL for HTTP/SSE servers
  if (config.type === 'http' || config.type === 'sse') {
    const httpConfig = config as { url?: string };
    if (httpConfig.url) {
      const match = EXA_API_KEY_PATTERN.exec(httpConfig.url);
      if (match) return match[1];
    }
  }

  // Check args for stdio servers
  if (!config.type || config.type === 'stdio') {
    const stdioConfig = config as { args?: string[] };
    if (stdioConfig.args) {
      for (const arg of stdioConfig.args) {
        const match = EXA_API_KEY_PATTERN.exec(arg);
        if (match) return match[1];
      }
    }
  }

  // Check env vars
  if ('env' in config && config.env) {
    const envConfig = config as { env: Record<string, string> };
    if (envConfig.env.EXA_API_KEY) {
      return envConfig.env.EXA_API_KEY;
    }
  }

  return undefined;
}

/** Result of filtering Exa MCP servers */
export interface ExaFilterResult {
  /** Configs with Exa servers removed */
  configs: Record<string, MCPServerConfig>;
  /** Extracted Exa API keys (if any) */
  exaApiKeys: string[];
  /** Source metadata for remaining servers */
  sources: Record<string, SourceMeta>;
}

/**
 * Filter out Exa MCP servers and extract their API keys.
 * Since we have native Exa integration, we don't need the MCP server.
 */
export function filterExaMCPServers(
  configs: Record<string, MCPServerConfig>,
  sources: Record<string, SourceMeta>,
): ExaFilterResult {
  const filtered: Record<string, MCPServerConfig> = {};
  const filteredSources: Record<string, SourceMeta> = {};
  const exaApiKeys: string[] = [];

  for (const [name, config] of Object.entries(configs)) {
    if (isExaMCPServer(name, config)) {
      // Extract API key before filtering
      const apiKey = extractExaApiKey(config);
      if (apiKey) {
        exaApiKeys.push(apiKey);
      }
    } else {
      filtered[name] = config;
      if (sources[name]) {
        filteredSources[name] = sources[name];
      }
    }
  }

  return { configs: filtered, exaApiKeys, sources: filteredSources };
}

/**
 * Validate server config has required fields.
 */
export function validateServerConfig(name: string, config: MCPServerConfig): string[] {
  const errors: string[] = [];

  const serverType = config.type ?? 'stdio';

  // Check for conflicting transport fields
  const hasCommand = 'command' in config && config.command;
  const hasUrl = 'url' in config && (config as { url?: string }).url;
  if (hasCommand && hasUrl) {
    errors.push(
      `Server "${name}": both "command" and "url" are set - server should be either stdio (command) OR http/sse (url), not both`,
    );
  }

  if (serverType === 'stdio') {
    const stdioConfig = config as { command?: string };
    if (!stdioConfig.command) {
      errors.push(`Server "${name}": stdio server requires "command" field`);
    }
  } else if (serverType === 'http' || serverType === 'sse') {
    const httpConfig = config as { url?: string };
    if (!httpConfig.url) {
      errors.push(`Server "${name}": ${serverType} server requires "url" field`);
    }
  } else {
    errors.push(`Server "${name}": unknown server type "${serverType}"`);
  }

  return errors;
}

/** Known browser automation MCP server names (lowercase) */
const BROWSER_MCP_NAMES = new Set([
  'puppeteer',
  'playwright',
  'browserbase',
  'browser-tools',
  'browser-use',
  'browser',
]);

/** Patterns matching browser MCP package names in command/args */
const BROWSER_MCP_PKG_PATTERN =
  // Official packages
  // - @modelcontextprotocol/server-puppeteer
  // - @playwright/mcp
  // - @browserbasehq/mcp-server-browserbase
  // - @agentdeskai/browser-tools-mcp
  // - @agent-infra/mcp-server-browser
  // Community packages: puppeteer-mcp-server, playwright-mcp, pptr-mcp, etc.
  /(?:@modelcontextprotocol\/server-puppeteer|@playwright\/mcp|@browserbasehq\/mcp-server-browserbase|@agentdeskai\/browser-tools-mcp|@agent-infra\/mcp-server-browser|puppeteer-mcp|playwright-mcp|pptr-mcp|browser-use-mcp|mcp-browser-use)/i;

/** URL patterns for hosted browser MCP services */
const BROWSER_MCP_URL_PATTERN = /browserbase\.com|browser-use\.com/i;

/**
 * Check if a server config is a browser automation MCP server.
 */
export function isBrowserMCPServer(name: string, config: MCPServerConfig): boolean {
  // Check by server name
  if (BROWSER_MCP_NAMES.has(name.toLowerCase())) {
    return true;
  }

  // Check by URL for HTTP/SSE servers
  if (config.type === 'http' || config.type === 'sse') {
    const httpConfig = config as { url?: string };
    if (httpConfig.url && BROWSER_MCP_URL_PATTERN.test(httpConfig.url)) {
      return true;
    }
  }

  // Check by command/args for stdio servers
  if (!config.type || config.type === 'stdio') {
    const stdioConfig = config as { command?: string; args?: string[] };
    if (stdioConfig.command && BROWSER_MCP_PKG_PATTERN.test(stdioConfig.command)) {
      return true;
    }
    if (stdioConfig.args?.some((arg) => BROWSER_MCP_PKG_PATTERN.test(arg))) {
      return true;
    }
  }

  return false;
}

/** Result of filtering browser MCP servers */
export interface BrowserFilterResult {
  /** Configs with browser servers removed */
  configs: Record<string, MCPServerConfig>;
  /** Source metadata for remaining servers */
  sources: Record<string, SourceMeta>;
}

/**
 * Filter out browser automation MCP servers.
 * Since we have a native browser tool, we don't need these MCP servers.
 */
export function filterBrowserMCPServers(
  configs: Record<string, MCPServerConfig>,
  sources: Record<string, SourceMeta>,
): BrowserFilterResult {
  const filtered: Record<string, MCPServerConfig> = {};
  const filteredSources: Record<string, SourceMeta> = {};

  for (const [name, config] of Object.entries(configs)) {
    if (!isBrowserMCPServer(name, config)) {
      filtered[name] = config;
      if (sources[name]) {
        filteredSources[name] = sources[name];
      }
    }
  }

  return { configs: filtered, sources: filteredSources };
}

