/**
 * System prompt construction and project context loading
 */

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import type { AgentTool } from '@oh-my-pi/pi-agent-core';
import {
  $env,
  getGpuCachePath,
  getProjectDir,
  hasFsCode,
  isEnoent,
  logger,
} from '@oh-my-pi/pi-utils';
import { $ } from 'bun';
import { contextFileCapability } from './capability/context-file';
import { systemPromptCapability } from './capability/system-prompt';
import { renderPromptTemplate } from './config/prompt-templates';
import type { SkillsSettings } from './config/settings';
import {
  type ContextFile,
  loadCapability,
  type SystemPrompt as SystemPromptFile,
} from './discovery';
import { loadSkills, type Skill } from './extensibility/skills';
import customSystemPromptTemplate from './prompts/system/custom-system-prompt.md' with { type: 'text' };
import systemPromptTemplate from './prompts/system/system-prompt.md' with { type: 'text' };
import { formatPromptContent } from './utils/prompt-format';

interface AlwaysApplyRule {
  name: string;
  content: string;
  path: string;
}

function normalizePromptBlock(content: string): string {
  return formatPromptContent(content, { renderPhase: 'post-render' }).trim();
}

function splitComparablePromptBlocks(content: string | null | undefined): string[] {
  const normalized = firstNonEmpty(content);
  if (!normalized) return [];

  return normalizePromptBlock(normalized)
    .split(/\n{2,}/)
    .map((block) => block.trim())
    .filter((block) => block.length > 0);
}

function promptSourceContainsRule(source: string | null | undefined, ruleContent: string): boolean {
  const sourceBlocks = splitComparablePromptBlocks(source);
  const ruleBlocks = splitComparablePromptBlocks(ruleContent);
  if (
    sourceBlocks.length === 0 ||
    ruleBlocks.length === 0 ||
    ruleBlocks.length > sourceBlocks.length
  )
    return false;

  for (let start = 0; start <= sourceBlocks.length - ruleBlocks.length; start += 1) {
    if (ruleBlocks.every((block, offset) => sourceBlocks[start + offset] === block)) return true;
  }

  return false;
}

function dedupeAlwaysApplyRules(
  alwaysApplyRules: AlwaysApplyRule[] | undefined,
  promptSources: Array<string | null | undefined>,
): AlwaysApplyRule[] {
  if (!alwaysApplyRules || alwaysApplyRules.length === 0) return [];

  return alwaysApplyRules.filter(
    (rule) => !promptSources.some((source) => promptSourceContainsRule(source, rule.content)),
  );
}

function dedupePromptSource(
  source: string | null | undefined,
  otherSources: Array<string | null | undefined>,
): string {
  const resolvedSource = firstNonEmpty(source);
  if (!resolvedSource) return '';

  return otherSources.some((otherSource) => promptSourceContainsRule(otherSource, resolvedSource))
    ? ''
    : resolvedSource;
}

function firstNonEmpty(...values: (string | undefined | null)[]): string | null {
  for (const value of values) {
    const trimmed = value?.trim();
    if (trimmed) return trimmed;
  }
  return null;
}

function parseWmicTable(output: string, header: string): string | null {
  const lines = output
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
  const filtered = lines.filter((line) => line.toLowerCase() !== header.toLowerCase());
  return filtered[0] ?? null;
}

const AGENTS_MD_MIN_DEPTH = 1;
const AGENTS_MD_MAX_DEPTH = 4;
const AGENTS_MD_LIMIT = 200;
const SYSTEM_PROMPT_PREP_TIMEOUT_MS = 5000;
const AGENTS_MD_EXCLUDED_DIRS = new Set(['node_modules', '.git']);

interface AgentsMdSearch {
  scopePath: string;
  limit: number;
  pattern: string;
  files: string[];
}

function normalizePath(value: string): string {
  return value.replace(/\\/g, '/');
}

function shouldSkipAgentsDir(name: string): boolean {
  if (AGENTS_MD_EXCLUDED_DIRS.has(name)) return true;
  return name.startsWith('.');
}

async function collectAgentsMdFiles(
  root: string,
  dir: string,
  depth: number,
  limit: number,
  discovered: Set<string>,
): Promise<void> {
  if (depth > AGENTS_MD_MAX_DEPTH || discovered.size >= limit) {
    return;
  }

  let entries: fs.Dirent[];
  try {
    entries = await fs.promises.readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }

  if (depth >= AGENTS_MD_MIN_DEPTH) {
    const hasAgentsMd = entries.some((entry) => entry.isFile() && entry.name === 'AGENTS.md');
    if (hasAgentsMd) {
      const relPath = normalizePath(path.relative(root, path.join(dir, 'AGENTS.md')));
      if (relPath.length > 0) {
        discovered.add(relPath);
      }
      if (discovered.size >= limit) {
        return;
      }
    }
  }

  if (depth === AGENTS_MD_MAX_DEPTH) {
    return;
  }

  const childDirs = entries
    .filter((entry) => entry.isDirectory() && !shouldSkipAgentsDir(entry.name))
    .map((entry) => entry.name)
    .sort();

  await Promise.all(
    childDirs.map(async (child) => {
      if (discovered.size >= limit) return;
      await collectAgentsMdFiles(root, path.join(dir, child), depth + 1, limit, discovered);
    }),
  );
}

async function listAgentsMdFiles(root: string, limit: number): Promise<string[]> {
  try {
    const discovered = new Set<string>();
    await collectAgentsMdFiles(root, root, 0, limit, discovered);
    return Array.from(discovered).sort().slice(0, limit);
  } catch {
    return [];
  }
}

async function buildAgentsMdSearch(cwd: string): Promise<AgentsMdSearch> {
  const files = await listAgentsMdFiles(cwd, AGENTS_MD_LIMIT);
  return {
    scopePath: '.',
    limit: AGENTS_MD_LIMIT,
    pattern: `AGENTS.md depth ${AGENTS_MD_MIN_DEPTH}-${AGENTS_MD_MAX_DEPTH}`,
    files,
  };
}

async function getGpuModel(): Promise<string | null> {
  switch (process.platform) {
    case 'win32': {
      const output = await $`wmic path win32_VideoController get name`
        .quiet()
        .text()
        .catch(() => null);
      return output ? parseWmicTable(output, 'Name') : null;
    }
    case 'linux': {
      const output = await $`lspci`
        .quiet()
        .text()
        .catch(() => null);
      if (!output) return null;
      const gpus: Array<{ name: string; priority: number }> = [];
      for (const line of output.split('\n')) {
        if (!/(VGA|3D|Display)/i.test(line)) continue;
        const parts = line.split(':');
        const name = parts.length > 1 ? parts.slice(1).join(':').trim() : line.trim();
        const nameLower = name.toLowerCase();
        // Skip BMC/server management adapters
        if (/aspeed|matrox g200|mgag200/i.test(name)) continue;
        // Prioritize discrete GPUs
        let priority = 0;
        if (
          nameLower.includes('nvidia') ||
          nameLower.includes('geforce') ||
          nameLower.includes('quadro') ||
          nameLower.includes('rtx')
        ) {
          priority = 3;
        } else if (
          nameLower.includes('amd') ||
          nameLower.includes('radeon') ||
          nameLower.includes('rx ')
        ) {
          priority = 3;
        } else if (nameLower.includes('intel')) {
          priority = 1;
        } else {
          priority = 2;
        }
        gpus.push({ name, priority });
      }
      if (gpus.length === 0) return null;
      gpus.sort((a, b) => b.priority - a.priority);
      return gpus[0].name;
    }
    default:
      return null;
  }
}

function getTerminalName(): string | undefined {
  const termProgram = Bun.env.TERM_PROGRAM;
  const termProgramVersion = Bun.env.TERM_PROGRAM_VERSION;
  if (termProgram) {
    return termProgramVersion ? `${termProgram} ${termProgramVersion}` : termProgram;
  }

  if (Bun.env.WT_SESSION) return 'Windows Terminal';

  const term = firstNonEmpty(Bun.env.TERM, Bun.env.COLORTERM, Bun.env.TERMINAL_EMULATOR);
  return term ?? undefined;
}

/** Cached system info structure */
interface GpuCache {
  gpu: string;
}

function getSystemInfoCachePath(): string {
  return getGpuCachePath();
}

async function loadGpuCache(): Promise<GpuCache | null> {
  try {
    const cachePath = getSystemInfoCachePath();
    const content = await Bun.file(cachePath).json();
    return content as GpuCache;
  } catch {
    return null;
  }
}

async function saveGpuCache(info: GpuCache): Promise<void> {
  try {
    const cachePath = getSystemInfoCachePath();
    await Bun.write(cachePath, JSON.stringify(info, null, '\t'));
  } catch {
    // Silently ignore cache write failures
  }
}

async function getCachedGpu(): Promise<string | undefined> {
  const cached = await logger.timeAsync('getCachedGpu:loadGpuCache', loadGpuCache);
  if (cached) return cached.gpu;
  const gpu = await logger.timeAsync('getCachedGpu:getGpuModel', getGpuModel);
  if (gpu) await logger.timeAsync('getCachedGpu:saveGpuCache', saveGpuCache, { gpu });
  return gpu ?? undefined;
}
async function getEnvironmentInfo(): Promise<Array<{ label: string; value: string }>> {
  const gpu = await logger.timeAsync('getEnvironmentInfo:getCachedGpu', getCachedGpu);
  const cpus = os.cpus();
  const entries: Array<{ label: string; value: string | undefined }> = [
    { label: 'OS', value: `${os.platform()} ${os.release()}` },
    { label: 'Distro', value: os.type() },
    { label: 'Kernel', value: os.version() },
    { label: 'Arch', value: os.arch() },
    { label: 'CPU', value: `${cpus[0]?.model}` },
    { label: 'GPU', value: gpu },
    { label: 'Terminal', value: getTerminalName() },
  ];
  return entries.filter((e): e is { label: string; value: string } => !!e.value);
}

/** Resolve input as file path or literal string */
export async function resolvePromptInput(
  input: string | undefined,
  description: string,
): Promise<string | undefined> {
  if (!input) {
    return undefined;
  } else if (input.includes('\n')) {
    return input;
  }

  try {
    return await Bun.file(input).text();
  } catch (error) {
    if (!hasFsCode(error, 'ENAMETOOLONG') && !isEnoent(error)) {
      logger.warn(`Could not read ${description} file`, { path: input, error: String(error) });
    }
    return input;
  }
}

export interface LoadContextFilesOptions {
  /** Working directory to start walking up from. Default: getProjectDir() */
  cwd?: string;
}

function dedupeExactContextFiles(
  contextFiles: Array<{ path: string; content: string; depth?: number }>,
): Array<{ path: string; content: string; depth?: number }> {
  const lastIndexByContent = new Map<string, number>();
  for (const [index, file] of contextFiles.entries()) {
    // Keep the closest matching context entry when content is byte-for-byte identical.
    lastIndexByContent.set(file.content, index);
  }

  return contextFiles.filter((file, index) => lastIndexByContent.get(file.content) === index);
}

/**
 * Load all project context files using the capability API.
 * Returns {path, content, depth} entries for all discovered context files.
 * Files are sorted by depth (descending) so files closer to cwd appear last/more prominent.
 */
export async function loadProjectContextFiles(
  options: LoadContextFilesOptions = {},
): Promise<Array<{ path: string; content: string; depth?: number }>> {
  const resolvedCwd = options.cwd ?? getProjectDir();

  const result = await loadCapability(contextFileCapability.id, { cwd: resolvedCwd });

  // Convert ContextFile items and preserve depth info
  const files = result.items.map((item) => {
    const contextFile = item as ContextFile;
    return {
      path: contextFile.path,
      content: contextFile.content,
      depth: contextFile.depth,
    };
  });

  // Sort by depth (descending): higher depth (farther from cwd) comes first,
  // so files closer to cwd appear later and are more prominent
  files.sort((a, b) => {
    const depthA = a.depth ?? -1;
    const depthB = b.depth ?? -1;
    return depthB - depthA;
  });

  return dedupeExactContextFiles(files);
}

/**
 * Load the effective system prompt customization from SYSTEM.md.
 * Project-level SYSTEM.md overrides user-level SYSTEM.md.
 */
export async function loadSystemPromptFiles(
  options: LoadContextFilesOptions = {},
): Promise<string | null> {
  const resolvedCwd = options.cwd ?? getProjectDir();

  const result = await loadCapability<SystemPromptFile>(systemPromptCapability.id, {
    cwd: resolvedCwd,
  });

  if (result.items.length === 0) return null;

  const projectLevel = result.items.find((item) => item.level === 'project');
  if (projectLevel) {
    return projectLevel.content;
  }

  const userLevel = result.items.find((item) => item.level === 'user');
  return userLevel?.content ?? null;
}

export interface SystemPromptToolMetadata {
  label: string;
  description: string;
}

export function buildSystemPromptToolMetadata(
  tools: Map<string, AgentTool>,
  overrides: Partial<Record<string, Partial<SystemPromptToolMetadata>>> = {},
): Map<string, SystemPromptToolMetadata> {
  return new Map(
    Array.from(tools.entries(), ([name, tool]) => {
      const toolRecord = tool as AgentTool & { label?: string; description?: string };
      const override = overrides[name];
      return [
        name,
        {
          label: override?.label ?? (typeof toolRecord.label === 'string' ? toolRecord.label : ''),
          description:
            override?.description ??
            (typeof toolRecord.description === 'string' ? toolRecord.description : ''),
        },
      ] as const;
    }),
  );
}

export interface BuildSystemPromptOptions {
  /** Custom system prompt (replaces default). */
  customPrompt?: string;
  /** Tools to include in prompt. */
  tools?: Map<string, SystemPromptToolMetadata>;
  /** Tool names to include in prompt. */
  toolNames?: string[];
  /** Text to append to system prompt. */
  appendSystemPrompt?: string;
  /** Repeat full tool descriptions in system prompt. Default: false */
  repeatToolDescriptions?: boolean;
  /** Skills settings for discovery. */
  skillsSettings?: SkillsSettings;
  /** Working directory. Default: getProjectDir() */
  cwd?: string;
  /** Pre-loaded context files (skips discovery if provided). */
  contextFiles?: Array<{ path: string; content: string; depth?: number }>;
  /** Skills provided directly to system prompt construction. */
  skills?: Skill[];
  /** Pre-loaded rulebook rules (descriptions, excluding TTSR and always-apply). */
  rules?: Array<{ name: string; description?: string; path: string; globs?: string[] }>;
  /** Intent field name injected into every tool schema. If set, explains the field in the prompt. */
  intentField?: string;
  /** Whether MCP tool discovery is active for this prompt build. */
  mcpDiscoveryMode?: boolean;
  /** Discoverable MCP server summaries to advertise when discovery mode is active. */
  mcpDiscoveryServerSummaries?: string[];
  /** Encourage the agent to delegate via tasks unless changes are trivial. */
  eagerTasks?: boolean;
  /** Rules with alwaysApply=true — their full content is injected into the prompt. */
  alwaysApplyRules?: AlwaysApplyRule[];
  /** Whether secret obfuscation is active. When true, explains the redaction format in the prompt. */
  secretsEnabled?: boolean;
}

/** Build the system prompt with tools, guidelines, and context */
export async function buildSystemPrompt(options: BuildSystemPromptOptions = {}): Promise<string> {
  if ($env.NULL_PROMPT === 'true') {
    return '';
  }

  const {
    customPrompt,
    tools,
    appendSystemPrompt,
    repeatToolDescriptions = false,
    skillsSettings,
    toolNames: providedToolNames,
    cwd,
    contextFiles: providedContextFiles,
    skills: providedSkills,
    rules,
    alwaysApplyRules,
    intentField,
    mcpDiscoveryMode = false,
    mcpDiscoveryServerSummaries = [],
    eagerTasks = false,
    secretsEnabled = false,
  } = options;
  const resolvedCwd = cwd ?? getProjectDir();

  const prepPromise = (() => {
    const systemPromptCustomizationPromise = logger.timeAsync(
      'loadSystemPromptFiles',
      loadSystemPromptFiles,
      {
        cwd: resolvedCwd,
      },
    );
    const contextFilesPromise = providedContextFiles
      ? Promise.resolve(providedContextFiles)
      : logger.timeAsync('loadProjectContextFiles', loadProjectContextFiles, { cwd: resolvedCwd });
    const agentsMdSearchPromise = logger.timeAsync(
      'buildAgentsMdSearch',
      buildAgentsMdSearch,
      resolvedCwd,
    );
    const skillsPromise: Promise<Skill[]> =
      providedSkills !== undefined
        ? Promise.resolve(providedSkills)
        : skillsSettings?.enabled !== false
          ? loadSkills({ ...skillsSettings, cwd: resolvedCwd }).then((result) => result.skills)
          : Promise.resolve([]);

    return Promise.all([
      resolvePromptInput(customPrompt, 'system prompt'),
      resolvePromptInput(appendSystemPrompt, 'append system prompt'),
      systemPromptCustomizationPromise,
      contextFilesPromise,
      agentsMdSearchPromise,
      skillsPromise,
    ]).then(
      ([
        resolvedCustomPrompt,
        resolvedAppendPrompt,
        systemPromptCustomization,
        contextFiles,
        agentsMdSearch,
        skills,
      ]) => ({
        resolvedCustomPrompt,
        resolvedAppendPrompt,
        systemPromptCustomization,
        contextFiles,
        agentsMdSearch,
        skills,
      }),
    );
  })();

  const prepResult = await Promise.race([
    prepPromise
      .then((value) => ({ type: 'ready' as const, value }))
      .catch((error) => ({ type: 'error' as const, error })),
    Bun.sleep(SYSTEM_PROMPT_PREP_TIMEOUT_MS).then(() => ({ type: 'timeout' as const })),
  ]);

  let resolvedCustomPrompt: string | undefined;
  let resolvedAppendPrompt: string | undefined;
  let systemPromptCustomization: string | null = null;
  let contextFiles: Array<{ path: string; content: string; depth?: number }> =
    dedupeExactContextFiles(providedContextFiles ?? []);
  let agentsMdSearch: AgentsMdSearch = {
    scopePath: '.',
    limit: AGENTS_MD_LIMIT,
    pattern: `AGENTS.md depth ${AGENTS_MD_MIN_DEPTH}-${AGENTS_MD_MAX_DEPTH}`,
    files: [],
  };
  let skills: Skill[] = providedSkills ?? [];

  if (prepResult.type === 'timeout') {
    logger.warn('System prompt preparation timed out; using minimal startup context', {
      cwd: resolvedCwd,
      timeoutMs: SYSTEM_PROMPT_PREP_TIMEOUT_MS,
    });
    process.stderr.write(
      `Warning: system prompt preparation timed out after ${SYSTEM_PROMPT_PREP_TIMEOUT_MS}ms; using minimal startup context.\n`,
    );
  } else if (prepResult.type === 'error') {
    logger.warn('System prompt preparation failed; using minimal startup context', {
      cwd: resolvedCwd,
      error: String(prepResult.error),
    });
    process.stderr.write(
      'Warning: system prompt preparation failed; using minimal startup context.\n',
    );
  } else {
    resolvedCustomPrompt = prepResult.value.resolvedCustomPrompt;
    resolvedAppendPrompt = prepResult.value.resolvedAppendPrompt;
    systemPromptCustomization = prepResult.value.systemPromptCustomization;
    contextFiles = dedupeExactContextFiles(prepResult.value.contextFiles);
    agentsMdSearch = prepResult.value.agentsMdSearch;
    skills = prepResult.value.skills;
  }

  const date = new Date().toISOString().slice(0, 10);
  const dateTime = date;
  const promptCwd = resolvedCwd.replace(/\\/g, '/');

  // Build tool metadata for system prompt rendering
  // Priority: explicit list > tools map > defaults
  // Default includes both bash and python; actual availability determined by settings in createTools
  let toolNames = providedToolNames;
  if (!toolNames) {
    if (tools) {
      // Tools map provided
      toolNames = Array.from(tools.keys());
    } else {
      // Use defaults
      toolNames = ['read', 'bash', 'python', 'edit', 'write']; // TODO: Why?
    }
  }

  // Build tool descriptions for system prompt rendering
  const toolInfo = toolNames.map((name) => ({
    name,
    label: tools?.get(name)?.label ?? '',
    description: tools?.get(name)?.description ?? '',
  }));

  // Filter skills to only include those with read tool
  const hasRead = tools?.has('read');
  const filteredSkills = hasRead ? skills : [];

  const effectiveSystemPromptCustomization = dedupePromptSource(systemPromptCustomization, [
    resolvedCustomPrompt,
    resolvedAppendPrompt,
  ]);
  const promptSources = [
    effectiveSystemPromptCustomization,
    resolvedCustomPrompt,
    resolvedAppendPrompt,
  ];
  const injectedAlwaysApplyRules = dedupeAlwaysApplyRules(alwaysApplyRules, promptSources);

  const environment = await logger.timeAsync('getEnvironmentInfo', getEnvironmentInfo);
  const data = {
    systemPromptCustomization: effectiveSystemPromptCustomization,
    customPrompt: resolvedCustomPrompt,
    appendPrompt: resolvedAppendPrompt || '',
    tools: toolNames,
    toolInfo,
    repeatToolDescriptions,
    environment,
    contextFiles,
    agentsMdSearch,
    skills: filteredSkills,
    rules: rules ?? [],
    alwaysApplyRules: injectedAlwaysApplyRules,
    date,
    dateTime,
    cwd: promptCwd,
    intentTracing: !!intentField,
    intentField: intentField ?? '',
    mcpDiscoveryMode,
    hasMCPDiscoveryServers: mcpDiscoveryServerSummaries.length > 0,
    mcpDiscoveryServerSummaries,
    eagerTasks,
    secretsEnabled,
  };
  return renderPromptTemplate(
    resolvedCustomPrompt ? customSystemPromptTemplate : systemPromptTemplate,
    data,
  );
}

/**
 * File verification for edit benchmark.
 *
 * Compares output files against expected fixtures with byte-for-byte equality.
 */
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { diffLines } from 'diff';
import { formatContent } from './formatter';

export interface VerificationResult {
  success: boolean;
  error?: string;
  duration: number;
  indentScore?: number;
  formattedEquivalent?: boolean;
  diffStats?: DiffStats;
  diff?: string;
}

export interface DiffStats {
  linesChanged: number;
  charsChanged: number;
}

async function listFiles(rootDir: string, subPath = ''): Promise<string[]> {
  const entries = await fs.readdir(path.join(rootDir, subPath), { withFileTypes: true });
  const files: string[] = [];

  for (const entry of entries) {
    const relativePath = path.join(subPath, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await listFiles(rootDir, relativePath)));
    } else if (entry.isFile()) {
      files.push(relativePath);
    }
  }

  return files.sort();
}

function formatFileList(files: string[]): string {
  return files.length === 0 ? '(none)' : files.join(', ');
}

function createCompactDiff(expected: string, actual: string, contextLines = 3): string {
  const changes = diffLines(expected, actual);
  const output: string[] = [];
  let lineNum = 1;

  for (let i = 0; i < changes.length; i++) {
    const change = changes[i]!;
    const lines = splitLines(change.value);

    if (change.added || change.removed) {
      // Show context before (from previous unchanged chunk)
      if (i > 0 && !changes[i - 1]!.added && !changes[i - 1]!.removed) {
        const prevLines = splitLines(changes[i - 1]!.value);
        const contextStart = Math.max(0, prevLines.length - contextLines);
        if (contextStart > 0) {
          output.push(`@@ -${lineNum - (prevLines.length - contextStart)} @@`);
        }
        for (let j = contextStart; j < prevLines.length; j++) {
          output.push(` ${prevLines[j]}`);
        }
      }

      // Show the change
      const prefix = change.added ? '+' : '-';
      for (const line of lines) {
        output.push(`${prefix}${line}`);
      }

      // Show context after (from next unchanged chunk)
      if (i + 1 < changes.length && !changes[i + 1]!.added && !changes[i + 1]!.removed) {
        const nextLines = splitLines(changes[i + 1]!.value);
        const contextEnd = Math.min(nextLines.length, contextLines);
        for (let j = 0; j < contextEnd; j++) {
          output.push(` ${nextLines[j]}`);
        }
      }

      if (!change.added) {
        lineNum += lines.length;
      }
    } else {
      lineNum += lines.length;
    }
  }

  return output.join('\n');
}

export async function verifyExpectedFiles(
  expectedDir: string,
  actualDir: string,
): Promise<VerificationResult> {
  return verifyExpectedFileSubset(expectedDir, actualDir);
}

export async function verifyExpectedFileSubset(
  expectedDir: string,
  actualDir: string,
  files?: string[],
): Promise<VerificationResult> {
  const startTime = Date.now();
  let totalIndentScore = 0;
  let fileCount = 0;

  try {
    const expectedFixtureFiles = await listFiles(expectedDir);
    const expectedFiles = files?.length ? files.slice().sort() : expectedFixtureFiles;
    const actualFiles = await listFiles(actualDir);

    const missingFiles = expectedFiles.filter((file) => !actualFiles.includes(file));
    const extraFiles = actualFiles.filter((file) => !expectedFiles.includes(file));
    const missingExpected = expectedFiles.filter((file) => !expectedFixtureFiles.includes(file));

    if (missingExpected.length > 0) {
      return {
        success: false,
        error: `Expected files missing from fixture: ${formatFileList(missingExpected)}`,
        duration: Date.now() - startTime,
      };
    }

    if (missingFiles.length > 0 || (files === undefined && extraFiles.length > 0)) {
      const parts: string[] = [];
      if (missingFiles.length > 0) {
        parts.push(`Missing files: ${formatFileList(missingFiles)}`);
      }
      if (files === undefined && extraFiles.length > 0) {
        parts.push(`Unexpected files: ${formatFileList(extraFiles)}`);
      }

      return {
        success: false,
        error: parts.join('; '),
        duration: Date.now() - startTime,
      };
    }

    for (const file of expectedFiles) {
      const expectedPath = path.join(expectedDir, file);
      const actualPath = path.join(actualDir, file);
      const expectedRaw = await Bun.file(expectedPath).text();
      const actualRaw = await Bun.file(actualPath).text();
      const expectedNormalized = normalizeLineEndings(expectedRaw);
      const actualNormalized = normalizeLineEndings(actualRaw);
      const actualNormalizedWithPreservedWhitespace = restoreWhitespaceOnlyLineDiffs(
        expectedNormalized,
        actualNormalized,
      );
      const expectedFormatted = await formatContent(
        expectedPath,
        normalizeBlankLines(expectedNormalized),
      );
      const actualFormatted = await formatContent(
        actualPath,
        normalizeBlankLines(actualNormalizedWithPreservedWhitespace),
      );
      const formattedEquivalent = expectedFormatted.formatted === actualFormatted.formatted;

      // Indent score: distance between agent's raw output and formatted output
      // This measures how much the formatter had to fix the agent's indentation
      const fileIndentScore = computeIndentDistanceForDiff(
        actualNormalized,
        actualFormatted.formatted,
      );
      totalIndentScore += fileIndentScore;
      fileCount++;

      // Fail if formatted versions don't match (content is wrong, not just whitespace)
      if (!formattedEquivalent) {
        const diffOutput = createCompactDiff(
          expectedFormatted.formatted,
          actualFormatted.formatted,
        );
        const diffStats = computeDiffStats(expectedFormatted.formatted, actualFormatted.formatted);
        return {
          success: false,
          error: `File mismatch for ${file}`,
          duration: Date.now() - startTime,
          diff: diffOutput,
          diffStats,
          indentScore: fileIndentScore,
          formattedEquivalent,
        };
      }
    }

    return {
      success: true,
      duration: Date.now() - startTime,
      indentScore: fileCount > 0 ? totalIndentScore / fileCount : 0,
      formattedEquivalent: true,
      diffStats: { linesChanged: 0, charsChanged: 0 },
    };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
      duration: Date.now() - startTime,
    };
  }
}

function computeDiffStats(expected: string, actual: string): DiffStats {
  const changes = diffLines(expected, actual);
  let linesChanged = 0;
  let charsChanged = 0;

  for (const change of changes) {
    if (!change.added && !change.removed) {
      continue;
    }
    const lines = splitLines(change.value);
    linesChanged += lines.length;
    charsChanged += change.value.length;
  }

  return { linesChanged, charsChanged };
}

function computeIndentDistanceForDiff(expected: string, actual: string): number {
  const changes = diffLines(expected, actual);
  let totalDistance = 0;
  let samples = 0;
  let pendingRemoved: string[] = [];
  let pendingAdded: string[] = [];

  const flush = () => {
    const max = Math.max(pendingRemoved.length, pendingAdded.length);
    for (let i = 0; i < max; i++) {
      const removedLine = pendingRemoved[i] ?? '';
      const addedLine = pendingAdded[i] ?? '';
      totalDistance += Math.abs(countIndent(removedLine) - countIndent(addedLine));
      samples += 1;
    }
    pendingRemoved = [];
    pendingAdded = [];
  };

  for (const change of changes) {
    const lines = splitLines(change.value);
    if (change.removed) {
      pendingRemoved.push(...lines);
      continue;
    }
    if (change.added) {
      pendingAdded.push(...lines);
      continue;
    }
    if (pendingRemoved.length > 0 ?? pendingAdded.length > 0) {
      flush();
    }
  }
  if (pendingRemoved.length > 0 || pendingAdded.length > 0) {
    flush();
  }

  return samples > 0 ? totalDistance / samples : 0;
}

function normalizeLineEndings(value: string): string {
  return value.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

/** Collapse runs of 2+ blank lines into a single blank line. */
function normalizeBlankLines(text: string): string {
  return text.replace(/\n{3,}/g, '\n\n');
}

function restoreWhitespaceOnlyLineDiffs(expected: string, actual: string): string {
  const expectedLines = expected.split('\n');
  const actualLines = actual.split('\n');
  const max = Math.max(expectedLines.length, actualLines.length);
  const out = new Array<string>(max);

  for (let i = 0; i < max; i++) {
    const expectedLine = expectedLines[i];
    const actualLine = actualLines[i];
    if (expectedLine === undefined || actualLine === undefined) {
      out[i] = actualLine ?? '';
      continue;
    }

    if (expectedLine !== actualLine && equalsIgnoringWhitespace(expectedLine, actualLine)) {
      out[i] = expectedLine;
    } else {
      out[i] = actualLine;
    }
  }

  return out.join('\n');
}

function equalsIgnoringWhitespace(a: string, b: string): boolean {
  return a.replace(/\s+/g, '') === b.replace(/\s+/g, '');
}

function splitLines(value: string): string[] {
  return value.split('\n').filter((line, idx, arr) => idx < arr.length - 1 || line);
}

function countIndent(line: string): number {
  let count = 0;
  for (const char of line) {
    if (char === ' ') {
      count += 1;
    } else if (char === '\t') {
      count += 2;
    } else {
      break;
    }
  }
  return count;
}

