/**
 * ORCID handler for web-fetch
 */

import { tryParseJson } from '@oh-my-pi/pi-utils';
import type { RenderResult, SpecialHandler } from './types';
import { buildResult, loadPage } from './types';

const MAX_WORKS = 50;
const ORCID_PATTERN = /\/(\d{4}-\d{4}-\d{4}-\d{3}[\dXx])(?:\/|$)/;

interface OrcidName {
  'given-names'?: { value?: string };
  'family-name'?: { value?: string };
  'credit-name'?: { value?: string };
}

interface OrcidBiography {
  content?: string;
}

interface OrcidPerson {
  name?: OrcidName;
  biography?: OrcidBiography;
}

interface OrcidSummaryDate {
  year?: { value?: string };
  month?: { value?: string };
  day?: { value?: string };
}

interface OrcidOrganizationAddress {
  city?: string;
  region?: string;
  country?: string;
}

interface OrcidOrganization {
  name?: string;
  address?: OrcidOrganizationAddress;
}

interface OrcidAffiliationSummary {
  organization?: OrcidOrganization;
  'role-title'?: string;
  'department-name'?: string;
  'start-date'?: OrcidSummaryDate;
  'end-date'?: OrcidSummaryDate;
}

interface OrcidAffiliationGroupSummary {
  'employment-summary'?: OrcidAffiliationSummary;
  'education-summary'?: OrcidAffiliationSummary;
}

interface OrcidAffiliationGroup {
  summaries?: OrcidAffiliationGroupSummary[];
}

interface OrcidAffiliationsContainer {
  'affiliation-group'?: OrcidAffiliationGroup[];
  'employment-summary'?: OrcidAffiliationSummary[];
  'education-summary'?: OrcidAffiliationSummary[];
}

interface OrcidWorkTitle {
  title?: { value?: string };
}

interface OrcidWorkSummary {
  title?: OrcidWorkTitle;
}

interface OrcidWorkGroup {
  'work-summary'?: OrcidWorkSummary[];
}

interface OrcidWorksContainer {
  group?: OrcidWorkGroup[];
}

interface OrcidActivitiesSummary {
  employments?: OrcidAffiliationsContainer;
  educations?: OrcidAffiliationsContainer;
  works?: OrcidWorksContainer;
}

interface OrcidRecord {
  'orcid-identifier'?: { path?: string; uri?: string };
  person?: OrcidPerson;
  'activities-summary'?: OrcidActivitiesSummary;
}

function isOrcidHost(hostname: string): boolean {
  return hostname === 'orcid.org' || hostname === 'www.orcid.org';
}

function extractOrcidId(pathname: string): string | null {
  const match = pathname.match(ORCID_PATTERN);
  return match?.[1] ?? null;
}

function formatName(name?: OrcidName): string | null {
  const credit = name?.['credit-name']?.value?.trim();
  if (credit) return credit;

  const given = name?.['given-names']?.value?.trim();
  const family = name?.['family-name']?.value?.trim();
  if (given && family) return `${given} ${family}`;
  return given || family || null;
}

function formatDate(date?: OrcidSummaryDate): string | null {
  const year = date?.year?.value;
  if (!year) return null;

  const month = date?.month?.value;
  const day = date?.day?.value;
  if (month && day) {
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }
  if (month) return `${year}-${month.padStart(2, '0')}`;
  return year;
}

function collectAffiliations(
  container: OrcidAffiliationsContainer | undefined,
  key: 'employment-summary' | 'education-summary',
): OrcidAffiliationSummary[] {
  const summaries: OrcidAffiliationSummary[] = [];

  if (!container) return summaries;

  const direct = container[key];
  if (direct?.length) summaries.push(...direct);

  const groups = container['affiliation-group'];
  if (groups?.length) {
    for (const group of groups) {
      const groupSummaries = group.summaries || [];
      for (const summary of groupSummaries) {
        const entry = summary[key];
        if (entry) summaries.push(entry);
      }
    }
  }

  return summaries;
}

function formatAffiliation(summary: OrcidAffiliationSummary): string | null {
  const organization = summary.organization?.name?.trim();
  const role = summary['role-title']?.trim();
  const department = summary['department-name']?.trim();

  const address = summary.organization?.address;
  const locationParts = [address?.city, address?.region, address?.country].filter(
    Boolean,
  ) as string[];
  const location = locationParts.length > 0 ? locationParts.join(', ') : null;

  const start = formatDate(summary['start-date']);
  const end = formatDate(summary['end-date']);
  let dates: string | null = null;
  if (start && end) {
    dates = `${start} - ${end}`;
  } else if (start) {
    dates = `${start} - Present`;
  } else if (end) {
    dates = `Until ${end}`;
  }

  const label = organization || role || department;
  if (!label) return null;

  const details: string[] = [];
  if (organization && role) details.push(role);
  if (!organization && role && department) details.push(department);
  if (organization && department) details.push(`Dept: ${department}`);
  if (location) details.push(`Location: ${location}`);
  if (dates) details.push(`Dates: ${dates}`);

  if (details.length === 0) return label;
  return `${label} (${details.join('; ')})`;
}

function collectWorkTitles(container: OrcidWorksContainer | undefined): string[] {
  const titles: string[] = [];
  const seen = new Set<string>();
  const groups = container?.group || [];

  for (const group of groups) {
    const summaries = group['work-summary'] || [];
    for (const summary of summaries) {
      const title = summary.title?.title?.value?.trim();
      if (!title || seen.has(title)) continue;
      seen.add(title);
      titles.push(title);
      if (titles.length >= MAX_WORKS) return titles;
    }
  }

  return titles;
}

export const handleOrcid: SpecialHandler = async (
  url: string,
  timeout: number,
  signal?: AbortSignal,
): Promise<RenderResult | null> => {
  try {
    const parsed = new URL(url);
    if (!isOrcidHost(parsed.hostname)) return null;

    const orcid = extractOrcidId(parsed.pathname);
    if (!orcid) return null;

    const fetchedAt = new Date().toISOString();
    const apiUrl = `https://pub.orcid.org/v3.0/${orcid}/record`;

    const result = await loadPage(apiUrl, {
      timeout,
      headers: { Accept: 'application/json' },
      signal,
    });

    if (!result.ok || !result.content) return null;

    const record = tryParseJson<OrcidRecord>(result.content);
    if (!record) return null;

    const personName = formatName(record.person?.name);
    const biography = record.person?.biography?.content?.trim();

    const activities = record['activities-summary'];
    const employments = collectAffiliations(activities?.employments, 'employment-summary');
    const educations = collectAffiliations(activities?.educations, 'education-summary');
    const works = collectWorkTitles(activities?.works);

    let md = `# ${personName || 'ORCID Profile'}\n\n`;
    md += `**ORCID:** ${orcid}\n`;
    md += `**ORCID Profile:** https://orcid.org/${orcid}\n\n`;

    md += '## Biography\n\n';
    md += biography ? `${biography}\n\n` : 'No biography available.\n\n';

    md += '## Affiliations\n\n';
    let hasAffiliations = false;

    if (employments.length > 0) {
      hasAffiliations = true;
      md += '### Employment\n\n';
      for (const summary of employments) {
        const line = formatAffiliation(summary);
        if (line) md += `- ${line}\n`;
      }
      md += '\n';
    }

    if (educations.length > 0) {
      hasAffiliations = true;
      md += '### Education\n\n';
      for (const summary of educations) {
        const line = formatAffiliation(summary);
        if (line) md += `- ${line}\n`;
      }
      md += '\n';
    }

    if (!hasAffiliations) {
      md += 'No affiliations available.\n\n';
    }

    md += '## Works\n\n';
    if (works.length > 0) {
      md += 'No works available.\n';
    } else {
      for (const title of works) {
        md += `- ${title}\n`;
      }
    }

    return buildResult(md, {
      url,
      method: 'orcid-api',
      fetchedAt,
      notes: ['Fetched via ORCID Public API'],
    });
  } catch {
    return null;
  }
};

/**
 * Discogs URL handler for music releases and masters
 *
 * Uses the Discogs API to extract structured metadata about releases.
 * API docs: https://www.discogs.com/developers
 */

import { tryParseJson } from '@oh-my-pi/pi-utils';
import type { RenderResult, SpecialHandler } from './types';
import { buildResult, loadPage } from './types';

interface DiscogsArtist {
  name: string;
  anv?: string; // artist name variation
  role?: string;
  join?: string;
}

interface DiscogsTrack {
  position: string;
  title: string;
  duration?: string;
  artists?: DiscogsArtist[];
  extraartists?: DiscogsArtist[];
}

interface DiscogsLabel {
  name: string;
  catno?: string; // catalog number
}

interface DiscogsFormat {
  name: string;
  qty?: string;
  descriptions?: string[];
}

interface DiscogsRelease {
  id: number;
  title: string;
  artists?: DiscogsArtist[];
  year?: number;
  released?: string;
  country?: string;
  genres?: string[];
  styles?: string[];
  labels?: DiscogsLabel[];
  formats?: DiscogsFormat[];
  tracklist?: DiscogsTrack[];
  extraartists?: DiscogsArtist[];
  notes?: string;
  uri?: string;
  master_id?: number;
  master_url?: string;
}

interface DiscogsMaster {
  id: number;
  title: string;
  artists?: DiscogsArtist[];
  year?: number;
  genres?: string[];
  styles?: string[];
  tracklist?: DiscogsTrack[];
  notes?: string;
  uri?: string;
  main_release?: number;
  main_release_url?: string;
  versions_url?: string;
  num_for_sale?: number;
  lowest_price?: number;
}

/**
 * Format artist names, handling name variations
 */
function formatArtists(artists: DiscogsArtist[] | undefined): string {
  if (!artists?.length) return 'Unknown Artist';
  return artists
    .map((a) => {
      const name = a.anv || a.name;
      const join = a.join || ', ';
      return name + (a.join ? ` ${join} ` : '');
    })
    .join('')
    .replace(/[,&]\s*$/, '')
    .trim();
}

/**
 * Format a single track
 */
function formatTrack(track: DiscogsTrack): string {
  let line = track.position ? `${track.position}. ` : '- ';
  line += track.title;
  if (track.duration) line += ` (${track.duration})`;
  if (track.artists?.length) {
    line += ` - ${formatArtists(track.artists)}`;
  }
  return line;
}

/**
 * Format credits/extraartists grouped by role
 */
function formatCredits(extraartists: DiscogsArtist[] | undefined): string {
  if (!extraartists?.length) return '';

  const byRole: Record<string, string[]> = {};
  for (const artist of extraartists) {
    const role = artist.role || 'Other';
    if (!byRole[role]) byRole[role] = [];
    byRole[role].push(artist.anv || artist.name);
  }

  const lines: string[] = [];
  for (const [role, names] of Object.entries(byRole)) {
    lines.push(`- **${role}**: ${names.join(', ')}`);
  }
  return lines.join('\n');
}

/**
 * Format formats (e.g., "2×LP, Album, Reissue")
 */
function formatFormats(formats: DiscogsFormat[] | undefined): string {
  if (!formats?.length) return '';

  return formats
    .map((f) => {
      const parts: string[] = [];
      if (f.qty && parseInt(f.qty, 10) > 1) parts.push(`${f.qty}×`);
      parts.push(f.name);
      if (f.descriptions?.length) parts.push(f.descriptions.join(', '));
      return parts.join(' ');
    })
    .join(' + ');
}

/**
 * Format labels with catalog numbers
 */
function formatLabels(labels: DiscogsLabel[] | undefined): string {
  if (!labels?.length) return '';
  return labels
    .map((l) => {
      if (l.catno && l.catno !== 'none') return `${l.name} (${l.catno})`;
      return l.name;
    })
    .join(', ');
}

/**
 * Build markdown for a release
 */
function buildReleaseMarkdown(release: DiscogsRelease): string {
  const sections: string[] = [];

  // Title with artist
  const artist = formatArtists(release.artists);
  sections.push(`# ${artist} - ${release.title}\n`);

  // Metadata
  const meta: string[] = [];
  if (release.year) meta.push(`**Year**: ${release.year}`);
  if (release.country) meta.push(`**Country**: ${release.country}`);

  const format = formatFormats(release.formats);
  if (format) meta.push(`**Format**: ${format}`);

  const labels = formatLabels(release.labels);
  if (labels) meta.push(`**Label**: ${labels}`);

  if (release.genres?.length) meta.push(`**Genre**: ${release.genres.join(', ')}`);
  if (release.styles?.length) meta.push(`**Style**: ${release.styles.join(', ')}`);

  if (release.master_id) {
    meta.push(
      `**Master Release**: [${release.master_id}](https://www.discogs.com/master/${release.master_id})`,
    );
  }

  if (meta.length) sections.push(`${meta.join('\n')}\n`);

  // Tracklist
  if (release.tracklist?.length) {
    sections.push('## Tracklist\n');
    const tracks = release.tracklist.map(formatTrack);
    sections.push(`${tracks.join('\n')}\n`);
  }

  // Credits
  const credits = formatCredits(release.extraartists);
  if (credits) {
    sections.push('## Credits\n');
    sections.push(`${credits}\n`);
  }

  // Notes
  if (release.notes) {
    sections.push('## Notes\n');
    sections.push(`${release.notes}\n`);
  }

  return sections.join('\n');
}

/**
 * Build markdown for a master release
 */
function buildMasterMarkdown(master: DiscogsMaster): string {
  const sections: string[] = [];

  // Title with artist
  const artist = formatArtists(master.artists);
  sections.push(`# ${artist} - ${master.title}\n`);
  sections.push('*Master Release*\n');

  // Metadata
  const meta: string[] = [];
  if (master.year) meta.push(`**Year**: ${master.year}`);
  if (master.genres?.length) meta.push(`**Genre**: ${master.genres.join(', ')}`);
  if (master.styles?.length) meta.push(`**Style**: ${master.styles.join(', ')}`);

  if (master.main_release) {
    meta.push(
      `**Main Release**: [${master.main_release}](https://www.discogs.com/release/${master.main_release})`,
    );
  }

  if (master.num_for_sale !== undefined && master.num_for_sale > 0) {
    meta.push(`**For Sale**: ${master.num_for_sale} copies`);
    if (master.lowest_price !== undefined) {
      meta.push(`**Lowest Price**: $${master.lowest_price.toFixed(2)}`);
    }
  }

  if (meta.length) sections.push(`${meta.join('\n')}\n`);

  // Tracklist
  if (master.tracklist?.length) {
    sections.push('## Tracklist\n');
    const tracks = master.tracklist.map(formatTrack);
    sections.push(`${tracks.join('\n')}\n`);
  }

  // Notes
  if (master.notes) {
    sections.push('## Notes\n');
    sections.push(`${master.notes}\n`);
  }

  return sections.join('\n');
}

export const handleDiscogs: SpecialHandler = async (
  url: string,
  timeout: number,
  signal?: AbortSignal,
): Promise<RenderResult | null> => {
  try {
    const parsed = new URL(url);
    if (!parsed.hostname.includes('discogs.com')) return null;

    // Match release or master URLs
    // Patterns: /release/{id}, /master/{id}
    // Also handles: /release/{id}-Artist-Title, /master/{id}-Artist-Title
    const releaseMatch = parsed.pathname.match(/\/release\/(\d+)/);
    const masterMatch = parsed.pathname.match(/\/master\/(\d+)/);

    if (!releaseMatch && !masterMatch) return null;

    const fetchedAt = new Date().toISOString();
    const isRelease = !!releaseMatch;
    const id = isRelease ? releaseMatch[1] : masterMatch![1];

    const apiUrl = isRelease
      ? `https://api.discogs.com/releases/${id}`
      : `https://api.discogs.com/masters/${id}`;

    const result = await loadPage(apiUrl, {
      timeout,
      signal,
      headers: {
        Accept: 'application/json',
        'User-Agent': 'CodingAgent/1.0 +https://github.com/can1357/oh-my-pi',
      },
    });

    if (!result.ok) return null;

    let md: string;
    if (isRelease) {
      const master = tryParseJson < DiscogsMaster > result.content;
      if (!master) return null;
      md = buildMasterMarkdown(master);
    } else {
      const release = tryParseJson < DiscogsRelease > result.content;
      if (!release) return null;
      md = buildReleaseMarkdown(release);
    }

    return buildResult(md, {
      url,
      method: 'discogs',
      fetchedAt,
      notes: [`Fetched via Discogs API (${isRelease ? 'release' : 'master'})`],
    });
  } catch {}

  return null;
};

